\begin{equation}
\label{eq.node_interconnector_state_space}
    \begin{aligned}
    \boldsymbol{A}
    &= 
    \begin{bmatrix}
        0
    \end{bmatrix}; 
    & \boldsymbol{B}
    &= 
    \begin{bmatrix}
        0_{1 \times \text{size}(\boldsymbol{D},2)}
    \end{bmatrix}; 
    \\
    \boldsymbol{C}
    &= 
    \begin{bmatrix}
        0_{2 \times 1}
    \end{bmatrix}; 
    & \boldsymbol{D}
    &= 
    \begin{bmatrix}
        \pm1 & 0 & \cdots & \pm1 & 0 \\
        0 & \pm1 & \cdots & 0 & \pm1
    \end{bmatrix};
