\subsection{Extension of Gallai's observation to infinite precedence graphs}

The following core result provides a necessary and sufficient condition for the existence of real solutions of precedence constraints, based on the precedence graph of the related difference bound matrix.
It was discovered by Gallai for finite difference bound matrices~\cite[Hilfssatz (2.2.1)]{gallai1958maximum}.
To the best of our knowledge, its extension to the case of generic infinite matrices is presented here for the first time. %
Its proof also provides a procedure for obtaining a solution when one exists.

\begin{theorem}\label{th:gallai}
    For a given $A\in \Rmax^{I\times I}$, inequality $x\geq A\otimes x$ admits a solution $x\in\R^I$ if and only if $\graph(A)\in\nonegset$.\footnote{This theorem remains valid if $\R$ is substituted by $\Z$, but not by $\Q$, because $\Q\cup\{\pm\infty\}$ is not closed for infinitely many $\oplus$.}
\end{theorem}


\zor{In order to prove the theorem, we need some technical definitions and lemmas.

\begin{definition}
Let $\preceq$ be a partial order relation on a set $I$.
We say that $\preceq$ is a \emph{good order} if the following conditions are satisfied:
\begin{itemize}
    \item $\preceq$ is a \emph{well-order} on $I$, i.e., a total order relation\footnote{A \emph{total order relation} $\preceq$ is a binary relation that is reflexive ($a\preceq a$), antisymmetric $(a\preceq b \wedge b\preceq a\Rightarrow a=b$), and transitive ($a\preceq b\wedge b\preceq c\Rightarrow a\preceq c$) such that, for every element $a,b$, either $a\preceq b$ or $b\preceq a$.} for which every nonempty subset of $I$ has a least element,
    \item for any element $a\in I$, there are finitely many elements less than or equal to $a$, i.e., $|\{x\in I\mid x\preceq a\}|\in\N$.\qedhere
\end{itemize}
\end{definition}
An example of well-order on $\N$ that is not good is the relation $\preceq$, defined such that $1\preceq 3\preceq 5\preceq 7\preceq \ldots \preceq 2\preceq 4\preceq 6\preceq 8\preceq \ldots$
\begin{lemma}\label{le:gallaiaux1}
    For any countable set $I$, there exists a good order on $I$.
\end{lemma}
\begin{proof}
By definition of countable set, there exists an injective function $f:I\rightarrow\N$.
Define the order $\preceq$ in $I$ such that, for all $a,b\in I$, $a\preceq b$ if and only if $f(a)\leq f(b)$.
Since $\leq$ is a good order on $\N$, then clearly the same can be said for the relation $\preceq$ on $I$.
\end{proof}
}

\zor{An example of good order on $\N\times\N$ is the one derived by the well-known Cantor pairing function $f((m,n)) = \frac{1}{2}(m+n-2)(m+n-1)+m$, which is a bijection from $\N\times\N$ to $\N$ \cite[page 169]{hopcroft1979introduction}.}

\begin{definition}
\zor{Let $A\in\Rbar^{I\times I}$, and let $\preceq$ be a good order on the set of pairs $I\times I$ (whose existence is guaranteed by \Cref{le:gallaiaux1}, since $I\times I$ is a countable set).
We define $\Phi:\Rbar^{I\times I}\rightarrow \Rbar^{I\times I}$ to be the function that, when applied on matrix $A$, returns $A^*$ if there is no pair $(i,j)$ such that $(A^*)_{ij}=-\infty$ and $(A^*)_{ji} \neq -\infty$,\footnote{In this case, if $A\in\Rmax^{I\times I}$, then $\graph(A)$ consists only of disjoint (i.e., not connected by arcs) maximal strongly connected subgraphs.}}
and otherwise returns
\[
    \Phi(A) = A^* \oplus (-(A^*)_{ji}) \otimes U_{(i,j)},
\]
\zor{where $(i,j)$ is the least pair, according to $\preceq$}, such that $(A^*)_{ij} = -\infty$ and $(A^*)_{ji}\neq-\infty$, $-(A^*)_{ji}$ simply indicates the opposite of $(A^*)_{ji}$ in the standard sense (\ie if $(A^*)_{ji}\in\R$, then $(A^*)_{ji}\otimes (-(A^*)_{ji})=0$, and if $(A^*)_{ji}=+\infty$, then $-(A^*)_{ji} = -\infty$), and $U_{(i,j)}\in\{-\infty,0\}^{I\times I}$ is $0$ in position $(i,j)$ and $-\infty$ everywhere else.
\end{definition}
Note that the exact definition of $\Phi$ depends on the \zor{chosen good order}, but the following discussion holds true for any admissible choice.

