\begin{lemma}\label{le:gallaiaux3}
\zor{For all $A\in\Rmax^{I\times I}$ such that $\graph(A)\in\nonegset$, $\graph(\Phi(A))\in\nonegset$.}
\end{lemma}
\begin{proof}
\zor{We will prove the lemma by assuming that $\graph(A)$ is connected; the reasoning can easily be extended to the case of nonconnected graph $\graph(A)$.}
Suppose that $\graph(A)\in\nonegset$ and assume, by means of contradiction, that $\graph(\Phi(A))\not\in \nonegset$.
If $\graph(A)$ is strongly connected, we immediately have a contradiction, since $\Phi(A) = A^*\in\Rmax^{I\times I}$.
If $\graph(A)$ is not strongly connected, then $\graph(\Phi(A))$ is identical to $\graph(A^*)$ except for having an additional arc $(j,i)$.
Since, from the hypothesis and~\eqref{eq:a_star_a_star}, $\graph(A^*)$ does not contain $\infty$-weight paths, the $\infty$-weight paths in $\graph(\Phi(A))$ must use the arc $(j,i)$, \ie all sequences of paths $\rho_1,\rho_2,\dots$ with $\lim_{k\rightarrow \infty} |\rho_k|_W = +\infty$ must satisfy: $\exists h\in\N$ such that $\forall k\geq h$, $\rho_k$ contains the arc $(j,i)$.
Recalling \Cref{re:elementary_paths_circuits}, we need to examine the existence of two types of objects: i. elementary circuits with positive weight, and ii. sequences of elementary paths with infinite limit weight.

i. Suppose that there is an elementary circuit with positive weight formed by concatenating arc $(j,i)$ with an elementary path $\rho$ from $i$ to $j$ consisting of arcs from $\graph(A^*)$.
Then, the weight of this path satisfies
\[
    |\rho|_{W} \otimes |(j,i)|_W \leq (A^*)_{ji} \otimes (-(A^*)_{ji}) = 0.
\]

ii. Assume that there is an infinite sequence of elementary paths $\rho_1,\rho_2,\dots$ from $\ell$ to $m$ passing through arc $(j,i)$ (exactly once).
Then, the weight of each path $\rho_k$ is bounded from above by
\[
    (A^*)_{mi} \otimes |(j,i)|_{W} \otimes (A^*)_{j\ell} = (A^*)_{mi} \otimes (-(A^*)_{ji}) \otimes (A^*)_{j\ell} \in \R.
\]

Thus, neither elementary circuits with positive weight nor sequences of paths with infinite limit weight exist, which implies a contradiction and, in turn, that $\graph(\Phi(A))\in\nonegset$.
\end{proof}

\begin{definition}
For all $A\in\Rbar^{I\times I}$, we define $A^\circledast\in\Rbar^{I\times I}$ as
\[
    A^\circledast = \lim_{k\rightarrow \infty} \Phi^k(A),
\]
where $\Phi^0(A) = A$ and $\Phi^{k+1}(A) = \Phi(\Phi^k(A))$.
\end{definition}

\zor{
