    \[
        \Phi^1(A) = 
\begin{bmatrix}
    0    &-3    &-3     &1  &-\infty\\
    0     &0    &-3  &-\infty  &-\infty\\
    0     &0     &0  &-\infty  &-\infty\\
    -1    &-1    &-1     &0     &2\\
    -\infty  &-\infty  &-\infty  &-\infty&     0
\end{bmatrix},\quad
        \Phi^2(A) = 
\begin{bmatrix}
