    The Kleene star of $A$ is\footnote{In this example, elements of $A^*$ and $A^\circledast$ were obtained by inspection using their graphical interpretation.}
    \[
        A^* = 
        \begin{bNiceMatrix}
            0 &  \cdot &     3 &  \cdot &     6 &  \cdot &     9 &  \cdot & \cdots\\
            0 &     0 &     3 &  \cdot &     6 &  \cdot &     9 &  \cdot & \cdots\\
            -4 &  \cdot &     0 &  \cdot &     3 &  \cdot &     6 &  \cdot & \cdots\\
            2 &     2 &     5 &     0 &     8 &  \cdot &    11 &  \cdot & \cdots\\
            -8 &  \cdot &    -5 &  \cdot &     0 &  \cdot &     3 &  \cdot & \cdots\\
            4 &     4 &     7 &  \cdot &    10 &     0 &    13 &  \cdot & \cdots\\
            -12 &  \cdot &    -9 &  \cdot &    -6 &  \cdot &     0 &  \cdot & \cdots\\
            6 &     6 &     9 &  \cdot &    12 &  \cdot &    15 &     0 & \cdots\\
            \vdots &     \vdots &     \vdots &  \vdots & \vdots &  \vdots & \vdots & \vdots & \ddots
        \end{bNiceMatrix}.
    \]
    \zor{Let us define $\Phi$ according to the good order $\preceq$ derived from the Cantor pairing function $f:\N\times\N\rightarrow\N$.}
    The precedence graph $\graph(A^*)$ consists of infinitely many maximal strongly connected subgraphs and, in this particular example, the sequence $\Phi^k(A)$ does not converge to $A^\circledast$ in finitely many steps, but only for $k\rightarrow \infty$.
    In the first application of $\Phi$, \zor{the least (according to $\preceq$)} pair $(i,j)$ such that $(A^*)_{ij}=-\infty$ and $(A^*)_{ji}\neq -\infty$ is $(1,2)$.
    Matrix $\Phi(A)$ with this choice coincides with $A^*$ except for entry $(1,2)$, which is equal to $0 = -(A^*)_{21}$.
    After infinitely many applications of $\Phi$, we would get
    \[
        A^\circledast = 
        \begin{bNiceMatrix}
            0 &      0 &     3 &    -2 &     6 &    -4 &     9 &    -6 & \cdots\\ 
            0 &     0 &     3 &    -2 &     6 &    -4 &     9 &    -6 & \cdots\\
            -4 &    -4 &     0 &    -6 &     3 &    -8 &     6 &   -10 & \cdots\\
            2 &     2 &     5 &     0 &     8 &    -2 &    11 &    -4 & \cdots\\
            -8 &    -8 &    -5 &   -10 &     0 &   -12 &     3 &   -14 & \cdots\\
            4 &     4 &     7 &     2 &    10 &     0 &    13 &    -2 & \cdots\\
            -12 &   -12 &    -9 &   -14 &    -6 &   -16 &     0 &   -18 & \cdots\\
            6 &     6 &     9 &     4 &    12 &     2 &    15 &     0 & \cdots\\
      \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \ddots 
        \end{bNiceMatrix}.
    \]
    We can now extract a solution of~\eqref{eq:example_potential_inequalities} from any column of $A^\circledast$.
    For instance, the first column provides the solution (written in standard algebra)
    \[
        x_k = 
        \begin{dcases}
            -4\cdot\frac{k-1}{2} & \mbox{if $k$ is odd,}\\
            2\cdot\frac{k-2}{2} & \mbox{if $k$ is even.}
        \end{dcases}
    \]
    Note that the first columns of $A^*$ and $A^\circledast$ are identical; the reason is that there is a path from node $1$ to any other node in $\graph(A)$.
    This illustrates a case in which the computation of $A^\circledast$ for finding solutions of precedence constraints can be avoided.
\end{example}

The procedure described in the proof of~\Cref{th:gallai} has significant theoretical value.
However, in the case of infinite difference bound matrices it does not immediately translate into a useful algorithm.\footnote{Recall the difference between an algorithm and a procedure; only algorithms need to terminate in finite time.}
In~\Cref{se:P_TEGs}, we will study interesting classes of precedence constraints with infinitely many variable\zor{s} in infinitely many inequalities where verifying whether a solution exists in finite time is always possible.

\section{$\N$-periodic graphs}\label{se:N_periodic_graphs}

In this section, we study a decision problem related to $\N$-periodic graphs.

\subsection{Definitions}

Let us first define static (or uniform) graphs. %

\begin{definition}[Static graph]
    Given three $n\times n$ matrices $L$, $C$, $R$ (standing, respectively, for "left", "center", and "right") with elements from $\Rmax$, the associated static graph $\graph = \graph(L,C,R) = (\nodes,\arcs,w)$ is the weighted multi-directed graph\footnote{\zor{In multi-directed graphs, there may be multiple arcs connecting two nodes.}} with set of nodes $\nodes = \dint{1,n}$, set of arcs $\arcs\subseteq \nodes\times \{-1,0,+1\}\times \nodes$, and weight function $w:\arcs\rightarrow \R$, defined such that there is an arc $e = (i,s,j)\in \arcs$ from the upstream node $i \eqqcolon \myup(e)$ to the downstream node $j \eqqcolon \mydown(e)$ with shift $s \eqqcolon \myshift(e)$ and weight $(X_{s})_{ji} \eqqcolon w(e)$ if and only if $(X_{s})_{ji} \neq -\infty$, where
\[
    X_s = 
    \begin{dcases}
        L & \mbox{if }s = -1,\\
        C & \mbox{if }s = 0,\\
        R & \mbox{if }s = +1.\qedlineend
    \end{dcases}
\]
\end{definition}

Every static graph induces (or generates) $\Z$-periodic, $\N$-periodic, and -- more generally -- $\S$-periodic graphs as follows.

\begin{definition}[$\S$-periodic graphs]
Let $\S$ be any subset of $\Z$ and let $\graph = \graph(L,C,R) = (\nodes,\arcs,w)$ be a static graph.
The $\S$-periodic graph $\graph_\S = \graph_\S(L,C,R) = (\nodes_{\S},\arcs_{\S},w)$ induced by $\graph$ is the (possibly infinite) weighted directed graph with set of nodes $\nodes_{\S} = \nodes \times \S$, set of arcs 
\[
    \arcs_\S = \{((i,k),(j,k+s))\mid (i,s,j)\in \arcs,\ k,k+s\in\S\},
\] 
and weight function\footnote{With slight abuse of notation, we denote by $w$ the weight functions of both $\graph$ and $\graph_\S$.} $w:\arcs_\S\rightarrow \R$ defined by $w(((i,k),(j,k+s))) = w((i,s,j))$.
The base and shift\footnote{The notation on static and $\S$-periodic graphs differs among publications. For instance, what here is called "shift" is referred as to "transit" in \cite{hoefting1995minimum,orlin1984some} and "height" in \cite{munier2011graph}. Moreover, $\N$-periodic graphs are called uniform graphs in \cite{munier2011graph}.} of a node $v_\S = (i,k)\in \nodes_\S$ are, respectively, $\myheight(v_\S) \coloneqq i$ and $\myshift(v_\S) \coloneqq k$.
For every arc $e_\S = ((i,k),(j,k+s))\in \arcs_\S$, let $\myup(e_\S) \coloneqq (i,k)$, $\mydown(e_\S) \coloneqq (j,k+s)$, $\myshift(e_\S) \coloneqq s$.
\end{definition}

\begin{example}\label{ex:simple_graph}
Figure~\ref{fi:static_periodic_graphs} illustrates the static graph associated with matrices 
\[
L = \begin{bmatrix}
        \alpha & -\infty\\-\infty & -3
    \end{bmatrix}, \ C = \begin{bmatrix}
        -\infty & -\infty\\0 & -\infty
    \end{bmatrix}, \ R = \begin{bmatrix}
        \beta & -\infty\\-\infty & 2
    \end{bmatrix},
\]
where $\alpha,\beta\in\R$, together with (portions of) its induced $\N$-periodic and $\Z$-periodic graphs.
\end{example}


$\Z$-periodic graphs have been studied under the name of periodic (or dynamic) graphs, see, \eg \cite{orlin1984some,hoefting1995minimum}.
By relabeling the nodes of a $\Z$-periodic graph $\graph_\Z$, we can see that it coincides with the precedence graph $\graph(M_\Z)$ of matrix
\[
    M_\Z = 
    \begin{bmatrix}
        \ddots & \vdots & \vdots & \vdots & \vdots & \iddots\\
        \cdots & C & L & \cdot & \cdot & \cdots\\
        \cdots & R & C & L & \cdot & \cdots\\
        \cdots & \cdot & R & C & L & \cdots\\
        \cdots & \cdot & \cdot & R & C & \cdots\\
        \iddots & \vdots & \vdots & \vdots & \vdots & \ddots
    \end{bmatrix}\in\Rmax^{\Z\times \Z},
\]
where each "$\cdot$" stands for \zor{the} $n\times n$ matrix $\mathcal{E}$.
$\N$-periodic graphs have incidence matrix of the form
\begin{equation}\label{eq:M_N}
    M_\N = 
    \begin{bmatrix}
        C & L & \cdot & \cdot & \cdots\\
        R & C & L & \cdot & \cdots\\
        \cdot & R & C& L & \cdots\\
        \cdot & \cdot & R & C& \cdots\\
        \vdots & \vdots & \vdots & \vdots & \ddots
    \end{bmatrix}\in\Rmax^{\N\times \N}.
\end{equation}

