\zor{\begin{example}
Observe that the graph in \Cref{fi:infinite_precedence_graph} is $\N$-periodic, while the one in \Cref{fi:graph_to_circledast} is not.
\end{example}}

To simplify the notation in the propositions of this section, it is convenient to provide alternative definitions of paths and circuits for static and $\S$-periodic graphs.
A path $p$ in either a static or an $\S$-periodic graph is an alternating sequence $p = (v_1,e_1,v_2,\ldots,v_m)$ of nodes $v_i$ and arcs $e_i$ such that $\myup(e_i) = v_i$ and $\mydown(e_i) = v_{i+1}$ for all $i\in\dint{1,m-1}$.
The length of $p$ is $\mylen(p) = m-1$.
A path $p$ is called circuit if $v_1\eqqcolon\myup(p)$ and $v_m\eqqcolon\mydown(p)$ coincide. %
A path $p$ in an $\S$-periodic graph is a pseudo-circuit if $\myheight(v_1) = \myheight(v_m)$.
Each node (resp., arc, path, pseudo-circuit) of an $\S$-periodic graph $\graph_\S$ corresponds to a unique node (resp., arc, path, circuit) of the associated static graph $\graph$.
On the other hand, each node (resp., arc, path, circuit) of $\graph$ induces infinitely many nodes (resp., arcs, paths, pseudo-circuits) of $\graph_\N$ and $\graph_\Z$.
The shift, weight, left-shift ($\mylshift$), and right-shift ($\myrshift$) of path $p$ are defined by\footnote{In the definition of $\mylshift$ and $\myrshift$, we assume by convention that the empty sum is equal to $0$.}
\[
    \myshift(p) = \sum_{i=1}^{m-1} \myshift(e_i),\quad
    \myweight(p) = \sum_{i=1}^{m-1} w(e_i),
\]
\[
    \mylshift(p) = \min_{i\in\dint{0,m-1}} \sum_{j=1}^{i} \myshift(e_j)\leq 0,\
    \myrshift(p) = \max_{i\in\dint{0,m-1}} \sum_{j=1}^i \myshift(e_j)\geq 0.
\]
Furthermore, if $p$ is a path in $\graph_\Z$, then it is also a path in $\graph_\N$ if and only if
\begin{equation}\label{eq:path_condition}
    \myshift(\myup(p))+\mylshift(p)\in\N.
\end{equation}
Let $p_1,p_2,\ldots,p_m$ be paths such that $\mydown(p_i) = \myup(p_{i+1})$ for all $i\in\dint{1,m-1}$.
Then we write $p_1p_2\cdots p_m$ to indicate the path obtained by concatenating $p_1,p_2,\ldots,p_m$.
If $p$ is a circuit and $x\in\N$, we define $p^x = p p^{x-1}$, where $p^0$ indicates the empty path, which has zero length.

\subsection{Detecting $\infty$-weight paths}\label{su:bounds}

Consider the following decision problem.\\[1.2mm]
\noindent
$\infty$-WEIGHT $\S$-PATH\\
\textbf{Instance:} Matrices $L,C,R\in\Rmax^{n\times n}$.\\
\textbf{Question:} Does $\graph_\S(L,C,R)$ contain an $\infty$-weight path?

\begin{example}\label{ex:simple_graph_2}
As an illustrative example, take the graphs of Figure~\ref{fi:static_periodic_graphs}.
For values $\alpha=-1,\beta=2$, both $\graph_\N$ and $\graph_\Z$ contain $\infty$-weight paths, as there exists a circuit with positive weight with source node $(1,k)$, for all $k$. %
Unlike finite graphs, however, $\S$-periodic graphs may contain $\infty$-weight paths even when there are no positive-weight circuits.
For example, this is the case for $\graph_\N$ and $\graph_\Z$ when $\alpha=-5,\beta=4$, as both of them contain an $\infty$-weight path from node $(1,k)$ to node $(2,k)$, for all $k$.
On the other hand, when $\alpha=-1,\beta=1$, only $\graph_\Z$ contains $\infty$-weight paths, each corresponding to a sequence of paths $p^k_1,p^k_2,\ldots$ with increasing weight from node $(1,k)$ to node $(2,k)$.
The same sequence cannot be built in $\graph_\N$, since for all $k\in\N$ and for $h$ large enough, $p^k_h$ does not satisfy~\eqref{eq:path_condition}, and thus is not a path in $\graph_\N$.
\end{example}

In \cite[Thorem 4.8]{hoefting1995minimum}, a polynomial-time algorithm that solves $\infty$-WEIGHT $\Z$-PATH was presented.
Munier Kordon solved the problem $\infty$-WEIGHT $\N$-PATH in weakly polynomial time \cite{munier2011graph}.\footnote{\zor{In \cite{munier2011graph}, it is assumed that, in the considered $\N$-periodic graph, there always exists a path with positive weight from any node $(i,k)$ to node $(i,k+h)$ for all $h\in\N$. This condition, however, does not seem to be essential for the algorithm proposed there.}}
In the following, we prove that any instance of $\infty$-WEIGHT $\N$-PATH can be solved in strongly polynomial time.

\begin{restatable}{lemma}{firstlemma}\label{le:length_supremal_path_N_periodic_graph}
Let $\graph$ be a static graph with $n$ nodes and let $i,j\in\dint{1,n}$.
Suppose that $\graph_\N$ does not contain $\infty$-weight paths from node $(i,1)$ to node $(j,1)$.
Then, the maximal weight of all paths from node $(i,1)$ to node $(j,1)$ in $\graph_\N$ is attained by a path with right-shift at most $n^2$.
\end{restatable}

The proof of \Cref{le:length_supremal_path_N_periodic_graph} can be found in \Cref{se:prooffirstlemma}.

Let us denote by $\Pi_{ij}(h)$ the supremal weight of all paths from node $(j,1)$ to node $(i,1)$ of right-shift at most $h\in\No$ in $\graph_{\N}$:
\[
    \begin{array}{rcl}
        \Pi_{ij}(h) &=& \sup \{\myweight(p)\mid p \mbox{ is a path in $\graph_{\N}$ from $(j,1)$ to $(i,1)$}\\
                    && \phantom{\sup \ \ \myweight(p)\mid} \mbox{and } \myrshift(p)\leq h\}\\
                    &=& \sup \{\myweight(p)\mid p \mbox{ is a path in $\graph_{\dint{1,h+1}}$ from $(j,1)$ to $(i,1)$}\}.
    \end{array} 
\] 
By definition,
\[
    \Pi_{ij}(+\infty) \coloneqq \lim_{h\rightarrow +\infty} \Pi_{ij}(h)
\] 
is the supremal weight of all paths in $\graph_{\N}$ from $(j,1)$ to $(i,1)$.
For all $h\in\No\cup\{+\infty\}$, we can construct matrix $\Pi(h)\in\Rbar^{n\times n}$ with $(i,j)$-element $(\Pi(h))_{ij} = \Pi_{ij}(h)$.
Note that $\Pi_{ij}(h)=-\infty$ if and only if there is no path from $(j,1)$ to $(i,1)$ with right-shift at most $h$.
Moreover, $\Pi_{ij}(h) = +\infty$ if and only if there is an $\infty$-weight path with right-shift at most $h$; as seen in \Cref{ex:simple_graph_2}, it is possible that $\Pi_{ij}(h)\in\Rmax$ for all $h\in\No$ and $\Pi_{ij}(+\infty) = +\infty$.
Using the max-plus algebra, we can get the following recursive formula for $\Pi(h)$ (for the proof, see \Cref{se:proofsecondlemma}).\footnote{\zor{A proof of \Cref{le:formula_Pi} can also be found in the technical report \cite{declerck2009extremal}.}}

\begin{restatable}{lemma}{secondlemma}\label{le:formula_Pi}
For all $h\in\No$, 
\[
    \begin{array}{rcl}
        \Pi(0) &=& C^+,\\
        \Pi(h+1) &=& (L \Pi(h)^* R \oplus C)^+.\qedlineend
    \end{array} 
\]
\end{restatable}


In algebraic terms, \Cref{le:length_supremal_path_N_periodic_graph} showed that, if $\graph_{\N}$ contains no $\infty$-weight paths from node $(i,1)$ to node $(j,1)$ for all $i,j\in\dint{1,n}$, then
\[
    \Pi(+\infty) = \Pi(n^2)\in\Rmax^{n\times n}.
\]
If $\infty$-weight paths from $(i,1)$ to $(j,1)$ exist for some $i,j$, then either $\Pi(n^2)\not\in\Rmax^{n\times n}$ (\ie there are circuits with positive weight and right-shift at most $n^2$), or we must have $\Pi(n^2+1)\neq\Pi(n^2)$.
If indeed the latter inequation were not true, then from the formula in \Cref{le:formula_Pi} we would have found a fixed point $\Pi(n^2)$ of mapping $F(\Pi) = (L\Pi^*R\oplus C)^+$, implying that $\Pi(n^2) = \Pi(n^2+1) = \Pi(n^2+2) =\dots = \Pi(+\infty)$.
This shows that \Cref{le:length_supremal_path_N_periodic_graph} gives a necessary and sufficient condition for the existence of $\infty$-weight paths between any nodes $(i,1)$ and $(j,1)$, where $i,j\in\dint{1,n}$.
In fact, in \Cref{se:proofthirdlemma} we prove the following, stronger result.

\begin{restatable}{lemma}{thirdlemma}\label{le:inf_weight_paths_N_periodic}
    Let $\graph$ be a static graph with $n$ nodes.
    Then $\graph_\N$ does not contain $\infty$-weight paths if and only if 
    \[
        \Pi(n^2+1) = \Pi(n^2) \mbox{ and }\Pi(n^2)\in\Rmax^{n\times n}.\qedlineend
    \]
\end{restatable} 

Because of \Cref{le:inf_weight_paths_N_periodic}, we can now state the main theorem of this section.
Recall that, given two matrices $A,B\in\Rmax^{n\times n}$, computing $A\oplus B$ and $A\otimes B$ using naive algorithms requires, respectively, $O(n^2)$ and $O(n^3)$ operations.\footnote{We assume to be working in the arithmetic model of computation, where standard operations between reals can be performed in constant time. All the time complexities given in this paper apply also in the Turing machine model, if reals are substituted by integers or rational numbers.}
Moreover, using the Floyd-Warshall algorithm, it is possible to verify the existence of circuits with positive weight in a graph $\graph(A)$ with $n$ nodes, and, if no such circuits exist, to compute $A^*$ in time $O(n^3)$ (see, e.g., \cite{cormen2022introduction}).

\begin{theorem}\label{th:polynomial_complexity}
The problem $\infty$-WEIGHT $\N$-PATH is solvable in strongly polynomial time complexity $O(n^5)$.
\end{theorem}
\begin{proof}
Given matrices $L,C,R\in\Rmax^{n\times n}$, we need to decide whether $\graph_\N = \graph_{\N}(L,C,R)$ contains an $\infty$-weight path.
According to \Cref{le:inf_weight_paths_N_periodic}, this can be done by computing $\Pi(0),\Pi(1),\dots,\Pi(n^2+1)$ and verifying, each time, whether $\Pi(h)\in\Rmax^{n\times n}$.
If for any $h\in\dint{0,n^2+1}$ we get $\graph(\Pi(h))\not \in\nonegset$, then the algorithm can be terminated as $\graph_{\N}$ contains a positive-weight circuit with shift at most $h$.
Otherwise, we need to check if $\Pi(n^2+1) = \Pi(n^2)$; the equality holds if and only if there are no $\infty$-weight paths in $\graph_\N$.

The whole procedure requires to compute at most $O(n^2)$ multiplications, additions, and Kleene stars on $n\times n$ matrices.
This results in an algorithm that terminates after $O(n^2n^3) = O(n^5)$ operations.
\end{proof}

\begin{example}\label{ex:simple_graph_3}
From the discussion carried out in Example~\ref{ex:simple_graph_2}, we know that $\graph_\N$ from \Cref{fi:static_periodic_graphs} contains an $\infty$-weight path only for certain parameters $\alpha,\beta$.
We can now verify this using \Cref{th:polynomial_complexity}.

For values $\alpha=-1,\beta=2$, it can be checked that $\graph(\Pi(0)) = \graph(C^+)\in\nonegset$, but $\graph(\Pi(1)) = \graph((LC^*R\oplus C)^+)\not\in \nonegset$; therefore, there is a positive-weight circuit with right-shift $1$. 
When $\alpha=-5,\beta=4$, observe that
\[
    \begin{bmatrix}
        -1 & -\infty\\5 & -1
    \end{bmatrix} = 
    \Pi(5) = \Pi(n^2+1) \neq \Pi(n^2) = \Pi(4) = 
    \begin{bmatrix}
        -1 & -\infty\\4 & -1
    \end{bmatrix}.
\]
Since $(\Pi(5))_{21} > (\Pi(4))_{21}$, there is an $\infty$-weight path starting from node $(1,1)$ and terminating in node $(2,1)$.
This means either that there is a positive-weight circuit with right-shift at least $6$ or that no positive-weight circuit exists but that there is an infinite sequence of elementary paths with infinite limit-weight.
In the considered case, it can be checked using the techniques presented in \cite{hoefting1995minimum,ZORZENON202219} that no positive-weight circuit exists, confirming that we are in the latter scenario.
On the other hand, when $\alpha=-1,\beta=1$, we have
\[
    \Pi(5) = 
    \Pi(4) = 
    \begin{bmatrix}
        0 & -\infty\\0 & -1
    \end{bmatrix}\in\Rmax^{2\times 2}.
\]
Thus, no $\infty$-weight path is present in this case.
\end{example}

\zor{\begin{remark}
We remark that the sequence of matrices $\{\Pi(h)\}_{h\in\No}$ defined in \Cref{le:formula_Pi} was first studied in \cite{5628259}.
What distinguishes our results from the one in \cite{5628259} is \Cref{le:inf_weight_paths_N_periodic}, which shows that computing the matrices up to $h=n^2+1$ is sufficient to decide the convergence of the sequence. 
\end{remark}}

\section{Ultimately periodic graphs}\label{se:ultimately_periodic_graphs}

In this section, we extend the results from \Cref{se:N_periodic_graphs} to the class of ultimately periodic graphs.

\subsection{Definitions}\label{su:definitions_ultimately_periodic_graphs}

Let $\graph_\wP = \graph(L_\wP,C_\wP,R_\wP) = (\nodes,\arcs_\wP,w_\wP)$ and $\graph_\wN = \graph(L_\wN,C_\wN,R_\wN) = (\nodes,\arcs_\wN,w_\wN)$ be two static graphs with the same set of nodes $\nodes = \dint{1,n}$, and let $C_\wT\in\Rmax^{n\times n}$ be a matrix.
The \emph{ultimately periodic graph} induced by $\graph_\wN$, $C_\wT$, and $\graph_\wP$ is the infinite weighted digraph $\graph_{\textup{U}} = \graph_{\textup{U}}(\graph_\wN,C_\wT,\graph_\wP) = (\nodes_{\textup{U}},\arcs_{\textup{U}},w_{\textup{U}})$ with set of nodes $\nodes_{\textup{U}} = \nodes\times \Z$, set of arcs\footnote{\zor{Note that, if $(i,s,j)\in\arcs_\wN\cup\arcs_\wP$, then $s\in\{-1,0,+1\}$. For this reason, the three conditions in the definitions of $\arcs_{\textup{U}}$ and $w_{\textup{U}}$ are mutually exclusive.}}
\[
    \arcs_{\textup{U}} = \left\{((i,k),(j,k+s))\ \left| \
        \begin{array}{cl}
                    &((k<0 \vee k+s<0) \wedge (i,s,j)\in \arcs_\wN) \\
\vee&((k>0 \vee k+s > 0) \wedge (i,s,j)\in \arcs_\wP) \\
\vee&(k = s = 0  \wedge (C_{\wT})_{ji}\neq -\infty)
        \end{array} 
        \right.
    \right\},
\]
and weight function $w_{\textup{U}}:\arcs_{\textup{U}}\rightarrow \R$ defined by
\[
    w_{\textup{U}}(((i,k),(j,k+s))) = 
    \begin{dcases}
        w_\wN((i,s,j)) & \mbox{if } k<0 \vee k+s < 0,\\
        w_\wP((i,s,j)) & \mbox{if } k>0 \vee k+s > 0,\\
        (C_\wT)_{ji} & \mbox{if } k=s=0.
    \end{dcases}
\]
Ultimately periodic graphs are the union of two periodic graphs -- a $\Z_{<0}$-periodic graph induced by $\graph_\wN$, called \emph{negative periodic part}, for nodes with negative shift and an $\N$-periodic graph induced by $\graph_\wP$, called \emph{positive periodic part}, for nodes with positive shift -- joined together via a finite graph $\graph(C_\wT)$ at zero shift called \emph{transient part}.
They are more general than $\Z$- and $\N$-periodic graphs, as ultimately periodic graphs with $X_\wN=X_\wP$ for all $X\in\{R,L\}$ and $C_\wN=C_\wT=C_\wP$ are $\Z$-periodic, and those with $X_\wN=\mathcal{E}$ for all $X\in\{R,L,C\}$ and $C_\wT=C_\wP$ are $\N$-periodic (except for having infinitely many additional nodes not connected to other nodes).
The definitions of paths and circuits are derived from those of $\S$-periodic graphs.
Each ultimately periodic graph can also be thought of as the precedence graph of matrix
\begin{equation}\label{eq:M_U}
    M_\textup{U} =
    \begin{bmatrix}
        \ddots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \iddots\\
        \cdots & C_\wN & L_\wN & \cdot & \cdot &\cdot & \cdot & \cdot & \cdots\\
        \cdots & R_\wN & C_\wN & L_\wN & \cdot &\cdot &\cdot & \cdot & \cdots\\
        \cdots & \cdot & R_\wN & C_\wN & L_\wN & \cdot &\cdot &\cdot &\cdots\\
        \cdots & \cdot & \cdot & R_\wN & C_\wT & L_\wP & \cdot &\cdot &\cdots\\
        \cdots & \cdot & \cdot & \cdot & R_\wP & C_\wP & L_\wP &\cdot &\cdots\\
        \cdots & \cdot&\cdot & \cdot &\cdot & R_\wP & C_\wP & L_\wP &\cdots\\
        \cdots & \cdot &\cdot & \cdot &\cdot & \cdot &R_\wP & C_\wP & \cdots\\
        \iddots & \vdots & \vdots & \vdots & \vdots& \vdots& \vdots & \vdots & \ddots
    \end{bmatrix}\in\Rmax^{\Z\times \Z}.
\end{equation}

