As for $\S$-periodic graphs, we can consider the following decision problem.\\[1.2mm]
\noindent
$\infty$-WEIGHT ULTIMATE-PATH\\
\textbf{Instance:} Matrices $L_\wN,C_\wN,R_\wN,C_\wT,L_\wP,C_\wP,R_\wP\in\Rmax^{n\times n}$.\\
\textbf{Question:} Does $\graph_{\textup{U}}(\graph_\wN,C_\wT,\graph_\wP)$, where $\graph_\wN = \graph(L_\wN,C_\wN,R_\wN)$ and $\graph_\wP = \graph(L_\wP,C_\wP,R_\wP)$, contain an $\infty$-weight path?

\subsection{Detecting $\infty$-weight paths}\label{su:longest_path_ultimately_periodic}

Define the mappings $\Pi_\wN,\Pi_\wP:\No\rightarrow\Rbar^{n\times n}$ recursively by
\[
    \begin{array}{rclrcl}
        \Pi_\wN(0) &=& C_\wN^+, & \Pi_\wP(0) &=& C_\wP^+,\\
         \Pi_\wN(h+1) &=& (R_\wN \Pi_\wN(h)^* L_\wN \oplus C_\wN)^+,& \quad
        \Pi_\wP(h+1) &=& (L_\wP \Pi_\wP(h)^* R_\wP \oplus C_\wP)^+.       
    \end{array} 
\]
The following lemma is proven in \Cref{se:prooffourthlemma}.

\begin{restatable}{lemma}{fourthlemma}\label{pr:infinite_weight_ultimately_periodic}
Let $\graph_{\textup{U}}$ be an ultimately periodic graph defined as above.
Then, $\graph_{\textup{U}}$ does not contains $\infty$-weight paths if and only if the following three conditions are satisfied:
    \begin{itemize}
    \item $\graph_\N(R_\wN,C_\wN,L_\wN)$ does not contain $\infty$-weight paths,
\item $\graph_\N(L_\wP,C_\wP,R_\wP)$ does not contain $\infty$-weight paths,
        \item $\graph(R_\wN \Pi_\wN(n^2)^* L_\wN \oplus C_\wT\oplus L_\wP \Pi_\wP(n^2)^* R_\wP)\in\nonegset$.\qedhere
    \end{itemize}
\end{restatable}

From the latter lemma, we can obtain an algorithm that checks the presence of $\infty$-weight paths and compute the supremal weight of paths in ultimately periodic graphs.
The algorithm has the same asymptotic time-complexity \zor{as} the one discussed in \Cref{su:bounds}.
This implies the following theorem.

\begin{theorem}\label{th:ultimately_periodic}
The problem $\infty$-WEIGHT ULTIMATE-PATH is solvable in strongly polynomial time complexity $O(n^5)$.
\end{theorem}

\begin{example}
    Take again the ultimately periodic graph from \Cref{ex:ultimately_periodic_graph}.
    It is possible to verify that $\Pi_\wN(16) = \Pi_\wN(17)\in\Rmax^{4\times 4}$ and $\Pi_\wP(16) = \Pi_\wP(17)\in\Rmax^{4\times 4}$.
    Therefore, neither the negative nor the positive periodic part of the graph contain $\infty$-weight paths.
    However, we get
    \[
        \graph(R_\wN \Pi_\wN(16)^* L_\wN \oplus C_\wT\oplus L_\wP \Pi_\wP(16)^* R_\wP ) = 
        \graph\left(\begin{bmatrix} 
            \cdot &\cdot &\cdot &0 \\
            1 &\cdot &\cdot &\cdot \\
            1 &\cdot &\cdot &\cdot \\
            -1 &0 &\cdot &\cdot 
    \end{bmatrix} \right)
        \not\in \nonegset.
    \]
    Thus, the graph contains a positive-weight circuit (highlighted in \Cref{fi:ultimately_periodic_graph}) visiting at least one node with zero shift.
\end{example}

\section{Consistency of P-time event graphs}\label{se:P_TEGs}

In this section we use \Cref{th:gallai}, \Cref{th:polynomial_complexity}, and \Cref{th:ultimately_periodic} for the analysis of P-time event graphs.
We start by recalling their definition and dynamics.

\subsection{P-time event graphs}

\begin{definition}[\cite{khansa1996p}]\label{de:PTPN}
An ordinary \textit{P-time Petri net} is a 5-tuple $(\places,\transitions,\arcs,\marking,\iota)$, in which $\places$ is a finite set of places, $\transitions$ is a finite set of transitions, $\arcs\subseteq (\places\times \transitions)\cup (\transitions \times \places)$ is the set of arcs connecting places to transitions and transitions to places, and $\marking:\places\rightarrow\No$ and $\iota:\places\rightarrow\{[\tau^-,\tau^+]\cap \R \mid \tau^-\in \R_{\geq 0},\tau^+\in\R_{\geq 0}\cup\{\infty\}\}$ are two maps that associate to each place $p\in\places$, respectively, its initial number of tokens (or marking) $\marking(p)$, and a time interval $\iota(p)=[\tau_p^-,\tau_p^+]\cap \R$. 
\end{definition}

The dynamics of ordinary P-time Petri nets evolves as follows.
A transition $t\in\transitions$ is said to be enabled if either it has no upstream places (i.e., $\forall p\in\places$, $(p,t)\notin\arcs$) or each upstream place $p\in \places$ contains at least one token that has resided in $p$ for a time included in interval $[\tau_p^-,\tau_p^+]\cap\R$.
Note that this time interval is always closed, unless $\tau_p^+=+\infty$, in which case it is of the form $[\tau_p^-,+\infty)$.
When transition $t$ is enabled, it can fire, causing one token to be instantaneously removed from each upstream place and one token to be instantaneously added to each downstream place.
If a token resides for too long in $p$, violating the constraint imposed by interval $[\tau_p^-,\tau_p^+]\cap \R$, then the token is said to be \textit{dead}.

In this paper, we focus on a subclass of P-time Petri nets called \textit{P-time event graphs} (P-TEGs).
A P-TEG is a P-time Petri net where each place has exactly one upstream and one downstream transition (\ie $\forall p\in \places$, $\exists ! (t_{\textup{up}},t_{\textup{down}})\in\transitions\times \transitions$ such that $(t_{\textup{up}},p)\in\arcs$ and $(p,t_{\textup{down}})\in\arcs$).

\begin{example}[Heat treatment unit]\label{ex:heat_treatment}
\begin{figure}[h]
    \centering
    \resizebox{.8\textwidth}{!}{
    \input{figures/TEG_furnace.tex}
    }
    \caption{P-TEG representing the heat treatment unit of \Cref{ex:heat_treatment}.}\label{fi:TEG_furnace}
\end{figure}
An example of P-TEG representing a heat treatment unit\zor{, consisting in a furnace and an autonomous guided vehicle (AGV),} is shown in \Cref{fi:TEG_furnace}.
Each firing of transition $t_1$ represents the arrival of a piece in \zor{the furnace.}
Every piece needs to be heated in \zor{the furnace} between $2$ and $3$ time units (see place $p_{21}$) to acquire the desired material properties.
\zor{The furnace has} capacity one (see place $p_{12}$), \ie \zor{it is} able to process one piece at a time.
The firing of transition $t_2$ indicates that one of the pieces has left \zor{the} furnace and has been loaded into \zor{the AGV}.
\zor{The AGV has} unitary capacity, and its purpose is to transport processed pieces to the next processing stage (not represented by the P-TEG) and then come back to the furnace.
A one-way journey of the AGV takes $0.5$ time units (see places $p_{32}$ and $p_{23}$).
The unloading of a piece from the AGV is indicated by the firing of transition $t_3$.
Customers require that one processed piece arrives at the next processing stage at most every $4$ time units (see place $p_{33}$).
Moreover, it is additionally required that pieces remain in the heat treatment unit (\ie furnace + AGV) at least for $6$ time units, in order to synchronize with other stages (see place $p_{31}$).
It is supposed that initially \zor{one part is} already being processed in the furnace, and that the AGV is ready to collect pieces from the furnace; this is reflected in the initial marking of the P-TEG.
\end{example}

We say that a P-TEG is \emph{consistent} if there exists an infinite sequence of firings of its transitions that does not cause any token death.
In order to study this property, it is convenient to state the dynamics of P-TEGs as a system of inequalities.
Before doing this, we need to clarify the role of initial conditions.

\subsection{Initial conditions}

Depending on the P-TEG application, different types of initial conditions may be considered.
In the following, we discuss two of them, called respectively loose and strict initial conditions.
The difference between them is in the time when initial tokens are allowed to contribute to the first firing of transitions.

In \emph{loose initial conditions}, initial tokens can contribute to the firing of transitions at any time, independently from the time interval associated to their initial place.
In particular, no time window constraint is imposed to initial tokens and, therefore, no initial token can become dead in its initial place.
Loose initial conditions are rather permissive, but they can be useful in some specific situations, for example to model the evolution of a system in stationary regime.

\begin{example}[Heat treatment unit, cont.]
If the P-TEG of \Cref{fi:TEG_furnace} works under loose initial conditions, then the first firing of transition $t_2$ can occur at any time $\tau\in\R$.
The first firing of $t_3$ may then not occur before time $\tau+0.5$; for instance, firing at time $\tau + 7$ would not cause token deaths.
\end{example}


\zor{In \emph{strict initial conditions}, instead, initial tokens are assumed to arrive in their initial places at an arbitrary \emph{initial time} $t_0\in\R$.
From this moment, a timer starts keeping track of the time the initial tokens spend in their respective initial places.
In particular, this means that, if the downstream transition of a place with an initial token and temporal upper bound $\tau^+\in\R_{\geq 0}$ does not fire before or at time $t_0+\tau^+$, then the initial token becomes dead.\footnote{\zor{In \cite{zorzenon2023switched}, strict initial conditions have been defined in another way using the concept of \emph{time tags}. It is easy to show that the two definitions are equivalent.}}}



\begin{example}[Heat treatment unit, cont.]\label{ex:heat_treatment_strict}
    \zor{Suppose that the P-TEG in \Cref{fi:TEG_furnace} is subject to strict initial conditions.
    Then, in order to avoid the death of the initial token in $p_{21}$, $t_2$ needs to fire for the first time between time $t_0+2$ and $t_0+3$.
Moreover, observe that the death of the initial token in $p_{33}$ is bound to occur, since the first firing of $t_3$ can only occur after $t_0+6$, because of the constraint associated to $p_{31}$, but should occur before $t_0+4$ to avoid the death of the initial token in $p_{33}$.
    This reasoning shows that the P-TEG, under strict initial conditions, is not consistent.}
\end{example}

\zor{Observe that, since P-TEGs are time-invariant systems, the choice of the value $t_0\in\R$ does not affect their dynamics.}

\subsection{Initial marking transformation}\label{su:marking_transformation}

\zor{We briefly recall that it} is always possible to transform a P-TEG into one in which the number of initial tokens in each place is at most $1$.
The transformation for P-TEGs with loose initial condition is described, \eg in \cite{paek2020analysis}\zor{, and it can be easily extended to the case of strict initial conditions.}

The transformation requires to add new places and transitions, and has the property of not modifying the allowed firing times of the transitions from the original P-TEG.
\zor{In particular, it} increases the number of transitions in the net from $|\transitions|$ to
\begin{equation}\label{eq:additional_transitions_transformation}
    |\transitions| + \sum_{p\in\places} \max\{ 0,\ \marking(p)-1\},
\end{equation}
where $\transitions$ and $\places$ are the set of transitions and places of the original P-TEG.



From now on, we will consider only P-TEGs with at most one \zor{initial} token per place, since any P-TEG can be transformed into a new one with this property.

\subsection{Dynamics as systems of inequalities}


We can now formulate the (nondeterministic) dynamics of a P-TEG $(\places,\transitions,\arcs,\marking,\iota)$ with $|\transitions| = n$ transitions and at most one initial token per place as the precedence constraints presented in the following.
Let us define matrices $A^0,A^1\in\Rmax^{n\times n}$ and $B^0,B^1\in\Rmin^{n\times n}$ such that, if there exists a place $p$ with initial marking $\mu\in\{0,1\}$, upstream transition $t_j$ and downstream transition $t_i$, then $A^\mu_{ij} = \tau_p^-$ and $B^\mu_{ij} = \tau_p^+$, otherwise $A^\mu_{ij} = -\infty$ and $B^\mu_{ij}=+\infty$.
Let $x_i(k)\in\R$ denote the time when transition $t_i\in\transitions$ fires for the $k$-th time, where $i\in\dint{1,n}$ and $k\in\N$.
Since the $(k+1)$-st firing of any transition $t_i$ cannot occur before the $k$-th one, it is natural to assume that $x_i$ is nondecreasing in $k$, i.e., $x_i(k+1) \geq x_i(k)$ for all $i\in\dint{1,n}$ and $k\in\N$.
The dynamics of a P-TEG under loose initial conditions can be described by the following system of infinitely many inequalities in infinitely many variables $x_i(k)$: for all $i,j\in\dint{1,n}$, $\mu\in\{0,1\}$, $k\in\N$,
\begin{equation}\label{eq:dynamics_PTEGs}
	\left\{
	\begin{array}{rcl}
	A^\mu_{ij} + x_j(k) \leq & x_i(k+\mu) & \leq B^\mu_{ij} + x_j(k),\\
	x_i(k) \leq & x_i(k+1). & 
	\end{array}
	\right.
\end{equation}
The meaning of the inequalities in the first line of~\eqref{eq:dynamics_PTEGs} is that, in order to satisfy the constraints imposed by the time interval $[\tau_p^-,\tau_p^+]$ associated to place $p$ with $\marking(p) = \mu$ initial tokens, the downstream transition $t_i$ of $p$ needs to fire for the $(k+\mu)$-th time at least $A_{ij}^\mu = \tau_p^-$ time units and at most $B_{ij}^\mu = \tau_p^+$ time units after the $k$-th firing of the upstream transition $t_j$ of $p$.
The second line of~\eqref{eq:dynamics_PTEGs} simply imposes the nondecreasingness condition on $x_i$.

In the case of strict initial conditions, we need to add inequalities to limit the first firing of transitions with upstream places containing initial tokens.
\zor{In particular, in addition to \eqref{eq:dynamics_PTEGs}, a P-TEG with strict initial conditions must satisfy}: for all $i,j\in\dint{1,n}$,
\begin{equation}\label{eq:dynamics_PTEGs_strict}
	\left\{
	\begin{array}{rcl}
    \zor{A^1_{ij}} + t_0 \leq & x_i(1) & \leq \zor{B^1_{ij}} + t_0,\\
	t_0 \leq & x_i(1). & 
	\end{array}
	\right.
\end{equation}

Note that matrices $A^0,A^1,B^0,B^1$ uniquely define a P-TEG with at most one initial token per place.
For this reason, they are called \emph{characteristic matrices} of the associated P-TEG.
We can now give a more formal definition of consistency: a P-TEG with loose (resp., strict) initial conditions is consistent if there exists an infinite trajectory $\{x_i(k)\in\R\mid i\in\dint{1,n},\ k\in\N\}$ that satisfies~\eqref{eq:dynamics_PTEGs} (resp., and \eqref{eq:dynamics_PTEGs_strict}).
Such a trajectory is then called consistent for the P-TEG, as it corresponds to an evolution of the marking in the P-TEG for which no token death occurs.

\subsection{Consistency with loose initial conditions}

In this section, we consider the following decision problem.

\noindent
P-TEG CONSISTENCY LOOSE\\
\textbf{Instance:} Matrices $A^0,A^1\in\Rmax^{n\times n}$, $B^0,B^1\in\Rmin^{n\times n}$.\\
\textbf{Question:} Is the P-TEG under loose initial conditions with characteristic matrices $A^0$, $A^1$, $B^0$, $B^1$ consistent?

To reduce the number of matrices involved, it is worth stating~\eqref{eq:dynamics_PTEGs} in the following, equivalent form
\begin{equation}\label{eq:simpler_dynamics}
	\begin{array}{l}
		\forall k\in\N,\\
		\forall i,j\in\dint{1,n},\\
	\end{array}
	\quad
	\left\{
	\begin{array}{rl}
		x_i(k) \geq & (L)_{ij} + x_j(k+1),\\
		x_i(k) \geq & (C)_{ij} + x_j(k),\\
		x_i(k+1) \geq & (R)_{ij} + x_j(k),
	\end{array}
	\right.
\end{equation}
where we used matrices $L,C,R\in\Rmax^{n\times n}$ defined by 
\[
 (L)_{ij} = -B^1_{ji}\quad   (C)_{ij} = \max\{A^0_{ij},\,-B^0_{ji}\},\quad 
	(R)_{ij} = 
    \begin{dcases}
        A^1_{ij} & \mbox{if } i\neq j,\\
        \max\{0,\, A^1_{ii}\} & \mbox{if }i = j,
    \end{dcases}.
\]
The equivalence between~\eqref{eq:dynamics_PTEGs} and~\eqref{eq:simpler_dynamics} can be easily verified using the fact that, for any $x,y,a,b\in\R$, the inequalities $x \geq a + y$ and $x\geq b + y$ hold if and only if $x \geq \max\{a + y,b + y\} = \max\{a,b\}+y$.
Even more compactly, we can write,
using the max-plus algebra,
\begin{equation}\label{eq:simple_dynamics_PTEGs}
	\forall k\in\N,
	\quad
	\left\{
	\begin{array}{rl}
		x(k) \geq & L \otimes x(k+1),\\
		x(k) \geq & C \otimes x(k),\\
		x(k+1) \geq & R \otimes x(k).
	\end{array}
	\right.
\end{equation}
Define $x_\N = [x(1)^\top\ x(2)^\top \cdots]^\top\in\R^\N$ and $M_{\N}\in\Rmax^{\N\times \N}$ as in~\eqref{eq:M_N}.
Then, \eqref{eq:simple_dynamics_PTEGs} can be rewritten as the precedence constraints $x_\N\geq M_\N\otimes x_\N$.
Therefore, the P-TEG corresponding to matrices $L,C,R$ is consistent if and only if $x_\N\geq M_\N\otimes x_\N$ admits a real solution $x_\N\in\R^\N$.
From \Cref{th:gallai}, the existence of a real solution is equivalent to $\graph(M_\N)$ not containing $\infty$-weight paths.
Recalling that $\graph(M_\N)$ is an $\N$-periodic graph, \Cref{th:polynomial_complexity} implies that it is possible to solve the problem P-TEG CONSISTENCY LOOSE in strongly polynomial time $O(n^5)$.

\begin{remark}
    According to the definition of P-TEG CONSISTENCY LOOSE, the input size depends on the number of transitions in the considered P-TEG after the marking transformation detailed in \Cref{su:marking_transformation}.
    Observe that the number of transitions added in the P-TEG by the transformation is, in the worst case, linear with respect to the number of initial tokens per place.
    Therefore, our discussion shows that consistency can be verified, in a P-TEG with arbitrary initial marking, in pseudo-polynomial time $O(\tilde{n}^5)$, where  $\tilde{n}$ is the number of transitions in the transformed P-TEG, evaluated in \eqref{eq:additional_transitions_transformation}.
\end{remark}

\begin{example}
\begin{figure}
	\centering
	\input{figures/P-TEG_example.tex}
	\caption{Example of P-TEG.}
	\label{fi:P-TEG_example}
\end{figure}

Consider the P-TEG represented in Figure~\ref{fi:P-TEG_example}.
Its characteristic matrices are
	\[A^0 = \begin{bmatrix}
	-\infty & -\infty \\
	0 & -\infty
\end{bmatrix},\quad
	A^1 = \begin{bmatrix}
	\beta & -\infty \\
	-\infty & 2
\end{bmatrix},\quad
	B^0 = \begin{bmatrix}\infty & \infty\\\infty & \infty\end{bmatrix},\quad
	B^1 = \begin{bmatrix}
	-\alpha & \infty \\
	\infty & 3
\end{bmatrix},\] 
where $\alpha\leq 0$, $\beta\geq 0$ are some parameters.
By applying the formulas for $L,C,R$, we get 
	\[L=-B^{1\top}=\begin{bmatrix}
	\alpha & -\infty\\-\infty & -3
	\end{bmatrix},\quad C = A^0\oplus (-B^{0\top})=
	\begin{bmatrix}
		-\infty & -\infty \\ 0 & -\infty
    \end{bmatrix},
	\]\[R = A^1\oplus E = \begin{bmatrix}
