\section{Proof of \Cref{le:length_supremal_path_N_periodic_graph}}\label{se:prooffirstlemma}

\firstlemma*
\begin{proof}
Let $\hat{p}_{(1)}$ be a path in $\graph_\N$ from $(i_{(1)},1)$ to $(j_{(1)},1)$ with maximal weight and minimal right-shift, where $i_{(1)}=i$ and $j_{(1)}=j$.
Note that, because this weight is finite and there are finitely many different weights of arcs in $\graph_\N$, such \zor{a} path must exist, in the sense that the supremal weight of all paths from $(i_{(1)},1)$ to $(j_{(1)},1)$ must be attained by a (finite) path.
\zor{Since $\myshift(\myup(\hat{p}_{(1)}))=1$,} clearly $\hat{p}_{(1)}$ has zero left-shift.

If $\myrshift(\hat{p}_{(1)}) > 1$, this path can be factored into $\hat{p}_{(1)} = \hat{s}_{(1)}\hat{p}_{(2)}\hat{t}_{(1)}$\footnote{There may be several ways to factorize $\hat{p}_{(1)}$ in this way. The following arguments can be applied to all of them.}, where $\hat{p}_{(2)}$ is a nonempty path from $(i_{(2)},2)$ to $(j_{(2)},2)$ with zero left-shift and right-shift $\myrshift(\hat{p}_{(2)}) = \myrshift(\hat{p}_{(1)})-1$, $\hat{s}_{(1)}$ is a path from $(i_{(1)},1)$ to $(i_{(2)},2)$, and $\hat{t}_{(1)}$ is a path from $(j_{(2)},2)$ to $(j_{(1)},1)$. 

We now prove by contradiction that $(i_{(1)},j_{(1)})\neq (i_{(2)},j_{(2)})$.
If $(i_{(1)},j_{(1)}) = (i_{(2)},j_{(2)})$, then $\hat{s}_{(1)}$ and $\hat{t}_{(1)}$ are two pseudo-circuits, and their corresponding paths $s_{(1)}$ and $t_{(1)}$ in the static graph $\graph$ are circuits.
Let $p_{(1)}$ (resp., $p_{(2)}$) be the path in $\graph$ corresponding to $\hat{p}_{(1)}$ (resp., $\hat{p}_{(2)}$), and suppose that $\myweight(s_{(1)})+\myweight(t_{(1)})>0$. 
Then, we can construct a sequence of paths $s_{(1)}^{x}p_{(2)}t_{(1)}^{x}$ in $\graph$ from node $i_{(1)}$ to node $j_{(1)}$ with weight increasing in $x\in\N$.
Observe that all such paths have zero left-shift; thus, they induce paths in $\graph_\N$ from $(i_{(1)},1)$ to $(j_{(1)},1)$ with increasing weight.
But this implies that there exists an $\infty$-weight path in $\graph_\N$ from $(i_{(1)},1)$ to $(j_{(1)},1)$, which is in contradiction with our hypotheses.
    On the other hand, if $(i_{(1)},j_{(1)}) = (i_{(2)},j_{(2)})$ and $\myweight(s_{(1)})+\myweight(t_{(1)})\leq 0$, then $\myweight(p_{(2)})\geq \myweight(p_{(1)})$.
As $p_{(2)}$ has zero left-shift, it induces a path in $\graph_{\N}$ from $(i_{(1)},1)$ to $(j_{(1)},1)$ with larger or equal weight and smaller right-shift compared to $\hat{p}_{(1)}$.
    This, once again, contradicts our hypotheses, as $\hat{p}_{(1)}$ is supposed to be the path with maximal weight and minimal right-shift from $(i_{(1)},1)$ to $(j_{(1)},1)$.
    Therefore, $(i_{(1)},j_{(1)}) \neq (i_{(2)},j_{(2)})$.

    It should be clear, from the definition of $\hat{p}_{(1)}$, that $\hat{p}_{(2)}$ is the path with maximal weight and minimal right-shift among those with zero left-shift from $(i_{(2)},2)$ to $(j_{(2)},2)$.
    Therefore, like $\hat{p}_{(1)}$, if $\myrshift(\hat{p}_{(2)}) = \myrshift(\hat{p}_{(1)}) - 1> 1$, it can be factored into $\hat{p}_{(2)} = \hat{s}_{(2)}\hat{p}_{(3)}\hat{t}_{(2)}$, where $\hat{p}_{(3)}$ is a path from $(i_{(3)},3)$ to $(j_{(3)},3)$ with zero left-shift and right-shift $\myrshift(\hat{p}_{(3)}) = \myrshift(\hat{p}_{(2)})-1$, $\hat{s}_{(2)}$ is a path from $(i_{(2)},2)$ to $(i_{(3)},3)$, and $\hat{t}_{(2)}$ is a path from $(j_{(3)},3)$ to $(j_{(2)},2)$.
    We therefore can repeat the same reasoning as before and show that $(i_{(3)},j_{(3)})\neq (i_{(2)},j_{(2)})$.
    The same reasoning can also be used to show that $(i_{(1)},j_{(1)})\neq (i_{(3)},j_{(3)})$.

Suppose, by means of contradiction, that $\myrshift(\hat{p}_{(1)}) > n^2$.
At the $(n^2+1)$-st application of the above procedure, we have found $n^2+1$ different pairs $(i_{(1)},j_{(1)}),\dots,(i_{(n^2+1)},j_{(n^2+1)})$ of numbers from $\dint{1,n}$.
But this is impossible, since there are exactly $n^2$ different pairs of numbers from $\dint{1,n}$.
Therefore, $\myrshift(\hat{p}_{(1)})\leq n^2$.
\end{proof}

\section{Proof of \Cref{le:formula_Pi}}\label{se:proofsecondlemma}

\secondlemma*
\begin{proof}
For $h = 0$, $\Pi_{ij}(0)$ coincides with the largest weight of paths in $\graph_{\dint{1,1}}$ from node $(j,1)$ to node $(i,1)$ or, equivalently, with the largest weight of paths in $\graph(C)$ from node $j$ to $i$; therefore $\Pi(0) = C^+$.

Observe that $\Pi(h+1)$ is the top-left $n\times n$ block of matrix
\begin{equation*}\label{eq:A_1h_plus}
    (M_{\dint{1,h+2}})^+ = 
    \begin{bNiceArray}{c|ccccc}
    C & L & \cdot & \cdots & \cdot & \cdot\\\hline
    R & C & L & \cdots& \cdot & \cdot\\
    \cdot & R & C& \cdots& \cdot & \cdot\\
    \vdots & \vdots & \vdots & \ddots& \vdots & \vdots\\
    \cdot & \cdot & \cdot & \cdots & C & L\\
    \cdot & \cdot & \cdot & \cdots & R & C
\end{bNiceArray}^+\in\Rbar^{((h+2)n)\times ((h+2)n)}.
\end{equation*}
Recall (\eg from \cite{baccelli1992synchronization}) the following formula for the Kleene plus in block matrices:
\[
    \begin{bmatrix}
        a & b\\c & d
    \end{bmatrix}^+ = 
    \begin{bmatrix}
        (\zor{bd^*c}\oplus a)^+ & \times\\ \times& \times
    \end{bmatrix},
\]
where each "$\times$" indicates an element not of interest for our discussion.
By direct application of the formula to compute the top-left $n\times n$ block of matrix $(M_{\dint{1,h+2}})^+$, we get
\[
    \Pi(h+1) = \left(
    \begin{bmatrix}
        L & \cdot & \cdots & \cdot & \cdot
    \end{bmatrix}\otimes (M_{\dint{1,h+1}})^* \otimes
    \begin{bmatrix}
        R\\\cdot\\\vdots\\\cdot\\\cdot
    \end{bmatrix} \oplus C
    \right)^+ = (L (\Pi(h)\oplus E) R \oplus C)^+.
\]
The proof is concluded by observing that $\Pi(h)\oplus E = \Pi(h)^*$.
\end{proof}

\section{Proof of \Cref{le:inf_weight_paths_N_periodic}}\label{se:proofthirdlemma}

\thirdlemma*
\begin{proof}
We have already seen that, if either $\Pi(n^2+1)\neq \Pi(n^2)$ or $\Pi(n^2)\not\in \Rmax^{n\times n}$, then there are $\infty$-weight paths in $\graph_\N$.
    Therefore, we just need to prove direction "$\Leftarrow$".
    As discussed above, if $\Pi(n^2+1) = \Pi(n^2)\in\Rmax^{n\times n}$, then there are no $\infty$-weight paths from node $(i,1)$ to node $(j,1)$, for all $i,j\in\dint{1,n}$.
We now show, by contrapositive, that this is enough to conclude that $\graph_\N$ does not contain $\infty$-weight paths from any node to any other node.
    In other words, we prove that if $\infty$-weight paths exist, then there is an $\infty$-weight path between nodes with unitary shift. 

Assume that $\graph_\N$ contains $\infty$-weight paths.
    According to \Cref{re:elementary_paths_circuits}, there are two possibilities: either there exists a positive-weight circuit or an infinite sequence of elementary paths with infinite limit-weight (or both).
    Suppose that a positive-weight circuit exists.
This circuit corresponds to a circuit in $\graph$ with positive weight and zero shift which, in turn, induces a circuit with positive weight visiting at least one node of the form $(i,1)$.
    Therefore, there exists a circuit with positive weight starting from node $(i,1)$.
    Then, as discussed above, either $\Pi(n^2)\not\in \Rmax^{n\times n}$ if the circuit has right-shift at most $n^2$ or $\Pi(n^2+1)\neq \Pi(n^2)$ otherwise.

    Suppose now that no positive-weight circuit exists.
    Then, there must be a sequence of elementary paths $p^{(1)},p^{(2)},\dots$ with infinite limit-weight from node $(i,h)$ to node $(j,k)$, for some $i,j\in\dint{1,n}$ and $h,k\in\N$.
    Let $h\leq k$; the proof for the case $h>k$ is analogous and therefore will not be explicitly addressed.
    Note that, a path from the sequence cannot visit nodes with shift $k$ for more than $n$ times, otherwise it would not be elementary.
    Therefore, any path $p^{(\ell)}$ from the sequence can be factored into
    \[
        p^{(\ell)} = w_1^{(\ell)} t_1^{(\ell)} w_2^{(\ell)} t_2^{(\ell)}\cdots w_{n-1}^{(\ell)} t_{n-1}^{(\ell)} w_n^{(\ell)},
    \]
    where $w_1^{(\ell)},\ldots,w_n^{(\ell)}$ are (possibly empty) paths visiting only nodes with shifts at most $k$, and $t_1^{(\ell)},\ldots,t_{n-1}^{(\ell)}$ are paths visiting only nodes with shift at least $k$.
    Moreover, since the number of nodes with shift at most $k$ is finite and each path $w_1^{(\ell)},\ldots,w_n^{(\ell)}$ is elementary, by the infinite pigeonhole principle there must be an infinite subsequence of paths $\tilde{p}^{(1)},\tilde{p}^{(2)},\dots$ with infinite limit-weight and with factorization
    \[
        \tilde{p}^{(\ell)} = w_1 t_1^{(\ell)} w_2 t_2^{(\ell)}\cdots w_{n-1} t_{n-1}^{(\ell)} w_n,
    \]
    where $w_1,\dots,w_n$ are independent on $\ell$.
    Since the weights of $w_1,\dots,w_n$ are constant in $\ell$, then there must exists at least one index $h\in\dint{1,n-1}$ such that the weight of $t^{(\ell)}_h$ has infinite weight for $\ell\rightarrow +\infty$.
    For the same reason, also the source and target nodes of $t^{(\ell)}_h$ are independent on $\ell$; we denote them by $\myup(t_h^{(\ell)})=(i',k)$ and $\mydown(t_h^{(\ell)})=(j',k)$.
    Thus, the sequence $t_h^{(1)},t_h^{(2)},\dots$ forms an $\infty$-weight path from $(i',k)$ to $(j',k)$.
    By definition, each path $t^{(\ell)}_h$ has zero left-shift.
Therefore, it can be translated so that its source node has shift $1$; in this way, we have obtained an $\infty$-weight path from $(i',1)$ to $(j',1)$ in $\graph_\N$.
\end{proof}

\section{Proof of \Cref{pr:infinite_weight_ultimately_periodic}}\label{se:prooffourthlemma}

\fourthlemma*
\begin{proof}
    Both directions of the proof are done by contrapositive.

    "$\Rightarrow$":
The graph $\graph_\N(R_\wN,C_\wN,L_\wN)$ is equivalent (up to renaming its nodes) to the negative periodic part of $\graph_\textup{U}$. 
The graph $\graph_\N(L_\wP,C_\wP,R_\wP)$, instead, coincides with the positive periodic part of $\graph_\textup{U}$.
Clearly, if one of these two graphs contains $\infty$-weight paths, then there are $\infty$-weight paths also in $\graph_{\textup{U}}$.
    From the discussion in \Cref{su:bounds}, we can see that 
    \[
    ((R_\wN \Pi_\wN(n^2)^* L_\wN \oplus C_\wT\oplus L_\wP \Pi_\wP(n^2)^* R_\wP )^+)_{ji}
    \]
    is the supremal weight of all paths starting from node $(i,0)$ and ending in $(j,0)$ with left-shift at least $-n^2$ and right-shift at most $n^2$.
    Therefore, if this value is $+\infty$, there exist\zor{s} an $\infty$-weight path in $\graph_\textup{U}$.

"$\Leftarrow$": we start by showing that, if $\graph_\textup{U}$ contains $\infty$-weight paths but $\graph_\N(R_\wN,C_\wN,L_\wN)$ and $\graph_\N(L_\wP,C_\wP,R_\wP)$ do not contain $\infty$-weight paths, then there must be a positive-weight circuit in $\graph_\textup{U}$ passing through node $(i,0)$ for some $i\in\dint{1,n}$.
Observe that, with these conditions, there cannot be a positive-weight circuit that does not visit any node with zero shift, otherwise either $\graph_\N(R_\wN,C_\wN,L_\wN)$ or $\graph_\N(L_\wP,C_\wP,R_\wP)$ contains $\infty$-weight paths.
Therefore, according to \Cref{re:elementary_paths_circuits}, we want to show that with these hypotheses there cannot be a sequence of elementary paths in $\graph_\textup{U}$ with infinite limit-weight.

    Suppose, by means of contradiction, that such a sequence exists.
Then, infinitely many paths of the sequence must visit at least one node with zero shift, otherwise either $\graph_\N(R_\wN,C_\wN,L_\wN)$ or $\graph_\N(L_\wP,C_\wP,R_\wP)$ contains $\infty$-weight paths.
    On the other hand, no path can visit a node with zero shift for more than $n$ times, otherwise it is not elementary.
    By the infinite pigeonhole principle, we can therefore find a subsequence of elementary paths $p^{(1)},p^{(2)},\dots$ that can be factored as 
    \[
        p^{(k)} = t^{(k)}_1w_1t^{(k)}_2w_2\cdots t^{(k)}_nw_nt^{(k)}_{n+1},
    \]
    where each $t^{(k)}_j$ is a (possibly empty) path visiting only nodes with non-zero shift, and each $w_j$ is a path (independent on $k$) visiting only nodes with shift $s\in\{-1,0,+1\}$.
    Since the sum of the weight of paths $w_1,\dots,w_n$ is independent on $k$, if the weight of $p^{(k)}$ tends to $+\infty$ for $k\rightarrow +\infty$, then there must exist at least one index $j\in\dint{1,n+1}$ such that the weight of $t^{(k)}_j$ tends to $+\infty$ for $k\rightarrow +\infty$.
But this implies that either $\graph_\N(R_\wN,C_\wN,L_\wN)$ or $\graph_\N(L_\wP,C_\wP,R_\wP)$ contains $\infty$-weight paths, which contradicts our hypotheses.
Therefore, there must exist a positive-weight circuit in $\graph_\textup{U}$ visiting at least one node with zero shift.

    Note that, using the formulas from \Cref{su:bounds}, the supremal weight of all circuits visiting node $(i,0)$ with left-shift at least $-k$ and right-shift at most $k$ (where $k\in\N$) is
    \[
        ((R_\wN \Pi_\wN(k)^* L_\wN \oplus C_\wT\oplus L_\wP\Pi_\wP(k)^* R_\wP )^+)_{ii}.
    \]
    Therefore, the supremal weight of all circuits visiting node $(i,0)$ (without conditions on their left- and right-shift) is
    \[
        \lim_{k\rightarrow +\infty}
        ((R_\wN \Pi_\wN(k)^* L_\wN \oplus C_\wT\oplus L_\wP\Pi_\wP(k)^* R_\wP )^+)_{ii}.
    \]
We have already seen in \Cref{su:bounds} that if $\graph_\N(L_\wP,C_\wP,R_\wP)$ does not contain $\infty$-weight paths, then $\lim_{k\rightarrow \infty} \Pi_\wP(k)= \Pi_\wP(n^2)$.
A similar reasoning shows that, if $\graph_\N(R_\wN,C_\wN,L_\wN)$ does not contain $\infty$-weight paths, then $\lim_{k\rightarrow \infty} \Pi_\wN(k)= \Pi_\wN(n^2)$.
We conclude that, if $\graph_\textup{U}$ contains $\infty$-weight paths, then either one of the graphs $\graph_\N(L_\wP,C_\wP,R_\wP)$ and $\graph_\N(R_\wN,C_\wN,L_\wN)$ contains $\infty$-weight paths, or there exists an entry in the diagonal of
    \[
        (R_\wN \Pi_\wN(n^2)^* L_\wN \oplus C_\wT\oplus L_\wP\Pi_\wP(n^2)^* R_\wP )^+
    \]
    that is equal to $+\infty$, \ie $\graph(R_\wN \Pi_\wN(n^2)^* L_\wN \oplus C_\wT\oplus L_\wP\Pi_\wP(n^2)^* R_\wP )\not \in \nonegset$.
\end{proof}

