\section*{Methods}
\subsection*{Ising and QUBO problems}
The Ising model and QUBO~(Quadratic Unconstrained Binary Optimization) are important mathematical models for solving combinatorial optimization problems. They are closely related (one-to-one correspondence) and can be applied to many practical problems.  The Ising model is a statistical mechanics model that describes the properties of magnetic materials.  It uses spin variables $s_{i}\;(\in \{-1,1\})$ as decision variables, and the Hamiltonian of the Ising model is expressed as shown in Eq.~(\ref{IsingEnergy}).  QUBO is an optimization problem with binary variables $b_{i}\;(\in \{0,1\})$ and a quadratic cost function as follows:

\begin{equation}
H_{\mathrm{QUBO}}=\sum_{i}^{N}\sum_{j}^{N}Q_{i,j}b_{i}b_{j},
\end{equation}
where $Q$ is referred to as the QUBO matrix.  The QUBO can be transformed into the Ising model using the following conversions.

\begin{align}
s_{i}&=2b_{i}-1,
\label{eq:conv1}\\
J_{i,j}&=
\begin{cases}
-\frac{Q_{i,j}}{2} & (\text{if}\;i\neq j),\\
0 & (\text{if}\;i= j),
\end{cases}
\label{eq:conv2}\\
h_{i}&=\sum_{j}^{N}\frac{Q_{i,j}}{2}.
\label{eq:conv3}
\end{align}

The MIS problem is formulated as a QUBO in \cite{lucas14,Hidaka23} as follows,

\begin{equation}\label{Eq_mis_b}
b_i=
\begin{cases}
1, & (\text{Node } i \text{ is an element of the independent set}),\\
0, & (\text{Node } i \text{ is not an element of the independent set}).
\end{cases}
\end{equation}
\begin{equation}\label{Eq_mis}
H_{\text{MIS}}=-B\sum_{i \in V}b_i + A\sum_{(i,j)\in E}b_ib_j.
\end{equation}
The first term corresponds to an objective fucntion to be minimized (an incentive to include more nodes) and the second term corresponds to a penalty function that increases if connected (not independent) edges ($\in E$) are included in the selected subset. The coefficients $A$ and $B$ determines the relative strength of each term.  This QUBO formulation is transformed into the Ising model using Equations Eqs.~(\ref{eq:conv1})-(\ref{eq:conv3}),
resulting in Eqs.~(\ref{Eq_mis_J}) and (\ref{Eq_mis_h}).

The WMMBG (Weighted Maximum Matching in Bipartite Graphs) is also formulated as a QUBO~\cite{Tatsumura24} as follows:

\begin{equation}\label{Eq_wmmbg_b}
b_{l,r}=
\begin{cases}
1, & (\text{if node $l$ and node $r$ are matched}),\\
0, & (\text{if node $l$ and node $r$ are unmatched}).
\end{cases}
\end{equation}
\begin{equation} \label{Eq_wmmbg}
		H_{\text{WMMBG}} = - \sum_{l=1}^n\sum_{r=1}^n W_{l,r}b_{l,r} +
		C\left( \sum\limits_{l=1}^n \Bigl( \sum\limits_{r=1}^n b_{l,r}-1 \Bigr) ^2 +
		\sum\limits_{r=1}^n \Bigl( \sum\limits_{l=1}^n b_{l,r}-1 \Bigr) ^2 \right),
\end{equation}
where $n$ is the number of nodes in an independent set (assuming for simplicity that the number of nodes in the two independent sets is the same), $C$ is a positive constant representing the constraint weight and $W_{l,r}$ represents the weight between node $l$ and node $r$.  The distribution of the $J$ when converted to the Ising model is shown in Fig.~\ref{Fig_IFCA}\textbf{a}.

G1 and G6 in Fig.~\ref{Fig_IFCA}\textbf{a} are the instances of the well-known G-set~\cite{Gset}, which serves as a benchmark for the MAX-CUT problem. The MAX-CUT involves partitioning the set of vertices of a graph into two subsets such that the sum of the weights of the edges cut by this partition is maximized. In the MAX-CUT, each vertex $i$ of the graph is assigned an Ising spin ($s_i=\pm 1$) whose sign represents a subset. The Hamiltonian of MAX-CUT is  defined as follows,

\begin{equation}\label{Eq_maxcut}
H_{\text{MAX-CUT}}=-\frac{1}{2}\sum_{(i,j) \in E} w_{i,j}(1-s_i s_j),
\end{equation}
where $E$ is the set of edges, and $w_{i,j}$ is the weight of the edge. In G1, the edge weights are binary, taking values of either -1 or 0, while in G6, the edge weights are ternary, taking values of -1, 0, or 1. Therefore, the possible values of the $J$-matrix are similarly limited.

The instance gr24 in Fig.~\ref{Fig_IFCA}\textbf{a} is from the TSPLIB~\cite{TSPLIB}, which serves as a benchmark for the TSP (Traveling Salesman Problem). TSP is a well-known example of a combinatorial optimization problem. Given the costs between all pairs of cities, it involves finding the route with the minimum total cost that visits each of the $n$ cities exactly once. The TSP can be formulated as a QUBO problem~\cite{lucas14}. Let $b_{i,j}$ be a binary variable that equals to 1 if city $i$ is visited at the $t$-th position, and 0 otherwise, the Hamiltonian of TSP is defined as follows,

\begin{equation}\label{Eq_tsp}
H_{\text{TSP}}=\sum_{t=1}^n\sum_{i=1}^n\sum_{j=1}^nd_{i,j}b_{t,i}b_{t+1,j}+C\left(\sum_{t=1}^n\left(\sum_{i=1}^nb_{t,i}-1\right)^2+\sum_{i=1}^n\left(\sum_{t=1}^nb_{t,i}-1\right)^2\right),
\end{equation}
where $d_{i,j}$ represents the distance between cities $i$ and $j$, $b_{n+1,i}=b_{1,i}$, and $C$ is a positive constant representing the constraint weight.

\subsection*{Simulated bifurcation}

Simulated bifurcation (SB)~\cite{sbm1,sbm2} is a quantum-inspired~\cite{sbm1,Qinspired24}, highly-parallelizable~\cite{FPL19,NatEle,Kashimata24}, metaheuristic algorithm for computationally-hard combinatorial (or discrete) optimization.  SB-based Ising machine belongs to a group of oscillator-based Ising machines~\cite{honjo21,kalinin20,PoorCIM19,moy22,albertsson21,wang21, SimCIM21,Graber24}.  The SB finds the optimal (exact) or near-optimal solution of the Ising problem by simulating the time-evolution process of coupled nonlinear oscillators according to the Hamilton's equations of motion (without energy-dissipative or noise-based mechanisms).  The SB has several variants including adiabatic SB, ballistic SB, and discrete SB, which differ in terms of nonlinearity~\cite{Nonlinearity21} anddiscreteness~\cite{sbm2}. 

In the SB, the $i$th nonlinear oscillator corresponds to the $i$th Ising spin and its state is described by the position and momentum ($x_i$, $y_i$). The update procedure of $x_i$ and $y_i$ for the ballistic SB, used in this work, is as follows~\cite{sbm2}.

\begin{align}
y_i^{t_{k\!+\!1}} &\gets y_i^{t_k} + \left[-(a_0-a^{t_k})x_i^{t_k} -\eta h_i + c_0\sum_{j}^{N}J_{i,j}x_j^{t_k}\right]\Delta_t,
\label{eq:y.bSB}\\
x_i^{t_{k\!+\!1}} &\gets x_i^{t_k} + a_0 y_i^{t_{k\!+\!1}}\Delta_t,
\label{eq:x.bSB}\\
(x_{i}^{t_{k\!+\!1}}, y_{i}^{t_{k\!+\!1}})&\gets
\left\{ 
\begin{alignedat}{2} 
(\mathrm{sgn}(x_{i}^{t_{k\!+\!1}}), 0) & \;\;(\text{if}\;|x_{i}^{t_{k\!+\!1}}|>1), \\
(x_{i}^{t_{k\!+\!1}}, y_{i}^{t_{k\!+\!1}}) & \;\;(\text{if}\;|x_{i}^{t_{k\!+\!1}}|\le1),
\end{alignedat} 
\right.
\label{eq:wall}
\end{align}
where $a_0$, $c_0$ and $\eta$ are positive constants, $a^{t_k}$ is a control parameter increasing from zero to $a_0$, and $\mathrm{sgn}(x) (=\pm 1)$ is the sign function.  Eq.~(\ref{eq:wall}) is a nonlinear transfer function~\cite{Nonlinearity21}, physically corresponding to a perfectly inelastic wallexisting at $x=\pm 1$.  The time increment is denoted as $\Delta_t$, and thus, $t_{k+1}=t_k+\Delta_t$.  After iterating the update procedure for the predetermined time steps ($N_{\rm step}$), the $i$th position $x_{i}$ is digitized to be the $i$th spin ($\pm 1$) by taking the sign of $x_{i}$.  In this work, $c_0 = \eta$ is denoted as $c$, $\Delta_t$ as $dt$, $N_{\text{step}}$ as $step$, and $a_0$ is set to 1. The values of $c, dt, step$ were estimated for each problem using the proposed parameter estimator with the assistance of machine learning.

The ballistic SB allows us to obtain better-quality solutions faster than the simulated annealing (SA) algorithm for academic benchmark problems~\cite{sbm2} and practical problems~\cite{Matsumoto22,ISCAS20,ACCESS23a,ACCESS23b,Hidaka23}.

\subsection*{Indexing fast-computing architecture}
This section describes the steps of a generalized indexing fast-computing architecture that is not limited to the MIS problem.  Algorithm~\ref{algo:gen_idx_table} shows the procedure for generating an indexed $J$-Table for any $J$-matrix.  Algorithm~\ref{algo:idx_encoding} describes the procedure for encoding a $J$-matrix with elements such as floating-point numbers using the indexed $J$-Table.  Algorithm~\ref{algo:idx_mac} presents a special MAC operation procedure for a variable $x$ with a known dynamic range (representable by fixed-point numbers) and the encoded $J^c$.  By using fixed-point numbers with a small bit width for the register and the adder of the ACC (accumulator), the resource amount for hardware implementation can be reduced.

\scriptsize
\begin{algorithm}[h]
\caption{Indexed $J$-Table generation}\label{algo:gen_idx_table}
\KwIn{The $J$-matrix of the Ising model, The number of Ising spins $N$.}
\KwOut{The indexed $J$-Table (TBL).}
$S \leftarrow \emptyset$\\
\For{$i \leftarrow 1$ \textbf{to} $N$} {
	\For{$j \leftarrow 1$ \textbf{to} $N$} {
		$S \leftarrow S \cup \{J_{i,j}\}$
	}
}
TBL $\leftarrow$ new array$[1..|S|]$\\
\For{$i \leftarrow 1$ \textbf{to} $|S|$} {
	TBL[$i$] $\leftarrow S_i$
}
\Return{$\mathrm{TBL}$}
\end{algorithm}
\normalsize

\scriptsize
\begin{algorithm}[h]
\caption{Index encoding}\label{algo:idx_encoding}
\KwIn{The $J$-matrix of the Ising model, The number of Ising spins $N$, and the indexed $J$-Table (TBL).}
\KwOut{The $J$-matrix encoded as $J^c$.}
$N_v \leftarrow \text{length}$(TBL)\\
$B$ $\leftarrow \lceil \log_2{N_v}\rceil$\\
Let $J^c$ be an array [1..$N$, 1..$N$] of $B$-bit integer\\

\tcp{\small Create a reverse dictionaly ReverseTBL for TBL.}
ReverseTBL $\leftarrow \{\}$\\
\For{$t \leftarrow 1$ \textbf{to} $N_v$} {
  ReverseTBL[TBL[$t$]] $\leftarrow t$
}
\tcp{\small Replace values with indexes.}
\For{$i \leftarrow 1$ \textbf{to} $N$} {
	\For{$j \leftarrow 1$ \textbf{to} $N$} {
    $J^c[i,j] \leftarrow$ ReverseTBL[$J[i,j]$]
	}
}
\Return{$J^c$}
\end{algorithm}
\normalsize

\scriptsize
\begin{algorithm}[h]
\caption{Indexed $J$-specialized MAC}\label{algo:idx_mac}
\KwIn{The variables $x$ defined in fixed-point notation, The $i$-th row of the matrix $J^c$ as $J^c_i$,
The number of Ising spins $N$, and the indexed $J$-Table (TBL).}
\KwOut{The result of the MAC operation as $\Delta y_i$}
$N_v \leftarrow \text{length}$(TBL)\\
$\Delta y_i \leftarrow 0$\\

\For{$t \leftarrow 1$ \textbf{to} $N_v$} {
  ACC $\leftarrow$ 0  \tcp{\small ACC is a fixed-point number.}
  \For{$j \leftarrow 1$ \textbf{to} $N$} {
    \If{$t = J^c_i[j]$}{
      $\text{ACC} \leftarrow \text{ACC} + x[j]$
    }
  }
  $\Delta y_i \leftarrow \Delta y_i + \text{convert\_to\_float(ACC) } \times$ TBL[$t$] \\
}

\Return{$\Delta y_i$}
\end{algorithm}
\normalsize


