\section{PDE-Aware Optimizer}
To resolve the gradient misalignment issues, we introduce a variant of Adam whose
second–moment accumulator is driven by per-sample physics-residual gradients. We compute the variance of the per-sample PDE gradients and divide each momentum component by the square root of that variance. Weights whose residual gradients fluctuate strongly across collocation points, therefore, take smaller steps, while those with consistent gradients move farther, giving the optimizer a built-in sensitivity to stiff regions, sharp fronts, or other difficult parts of the solution. Because the first-moment term is the batch-average of those same residual gradients, the update direction is aligned with the dominant physics signal and is less disturbed by initial- or boundary-condition terms that may point elsewhere.

%------------------- theory ------------------------------------

For a mini-batch of $B$ collocation points
$\{x_i\}_{i=1}^{B}$ we compute
\begin{equation}
\bm{g}_i \;=\;
\nabla_{\bm{w}}\,R_{\mathrm{pde}}(x_i;\bm{w}_t),
\qquad
\overline{\bm{g}}
\;=\;
\frac{1}{B}\sum_{i=1}^{B}\bm{g}_i .
\end{equation}

\begin{align}
\bm{m}_t &=
  \beta_1\,\bm{m}_{t-1} + (1-\beta_1)\,\overline{\bm{g}},
\\
\bm{v}_t &=
  \beta_2\,\bm{v}_{t-1}
  +\frac{1-\beta_2}{B}\sum_{i=1}^{B}\bm{g}_i^{\odot 2},
\label{eq:variance-update}
\\
\bm{w}_{t+1} &=
  \bm{w}_t
  -\eta\,\frac{\bm{m}_t}{\sqrt{\bm{v}_t}+\epsilon},
\label{eq:update}
\end{align}
where $\odot$ denotes the element-wise square.
Because each coordinate $m_t^{(j)}$ is scaled by
$\bigl(\sqrt{v_t^{(j)}}+\epsilon\bigr)^{-1}$, the step size is
\emph{smaller} where the residual gradient varies strongly across the
batch and \emph{larger} where it is coherent, focusing adaptation on
difficult physics regions rather than on the total loss.

%------------------- algorithm ---------------------------------
\begin{algorithm}[H]
\caption{PDE-Aware Optimizer for training PINNs}
\label{alg:pao}
\begin{algorithmic}[1]
  \Require initial parameters $\bm{w}_0$,
          learning rate $\eta$,
          decay rates $\beta_1,\beta_2$,
          batch size $B$,
          small constant $\epsilon$
  \Ensure  trained parameters $\bm{w}_T$
  \State $\bm{m}_{-1}\gets\bm{0}$ \Comment{first moment}
  \State $\bm{v}_{-1}\gets\bm{0}$ \Comment{second moment}
  \For{$t = 0$ \textbf{to} $T-1$}
    \ForAll{$x_i$ in mini-batch}
       \State $\bm{g}_i\gets
              \nabla_{\bm{w}}\,R_{\mathrm{pde}}(x_i;\bm{w}_t)$
    \EndFor
    \State $\displaystyle
           \overline{\bm{g}}\gets
           \frac1B\sum_{i=1}^{B}\bm{g}_i$
    \State $\bm{m}_t\gets
           \beta_1\bm{m}_{t-1} + (1-\beta_1)\,\overline{\bm{g}}$
    \State $\displaystyle
           \bm{v}_t\gets
           \beta_2\bm{v}_{t-1}
           +\frac{1-\beta_2}{B}\sum_{i=1}^{B}\bm{g}_i^{\odot 2}$
    \State $\tilde{\bm{m}}_t\gets
           \bm{m}_t \,/\,\bigl(\sqrt{\bm{v}_t}+\epsilon\bigr)$
    \State $\bm{w}_{t+1}\gets\bm{w}_t-\eta\,\tilde{\bm{m}}_t$
  \EndFor
\end{algorithmic}
\end{algorithm}
\begin{figure}[t]
  \centering
  \includegraphics[width=.55\linewidth]{algorithm.png}
  % Short caption in optional argument, full caption in mandatory one
  \caption[PAO flow chart]{Flow chart of the \textbf{PDE-Aware Optimizer}.
  The first moment $\bm{m}_t$ is built from batch-averaged PDE‐residual
  gradients; the second moment $\bm{v}_t$ tracks their element-wise
  variance, so the pre-conditioned step
  $\bm{w}_{t+1}=\bm{w}_t-\eta\,\bm{m}_t/(\sqrt{\bm{v}_t}+\epsilon)$
  automatically shrinks learning rates in stiff regions and enlarges them
  where the residual is smooth.}
  \label{fig:pao-flow}
\end{figure}


%============================================================
\section{Experimental Setup}

Following common practice in PINNs literature, we benchmark the proposed
Physics-Aware Optimizer on three canonical 1-D PDEs:
Burgers’ convection–diffusion equation, the Allen–Cahn
reaction–diffusion equation and the Korteweg–De Vries wave equation.  
%------------------------------------------------------------
\paragraph{PDE benchmarks:}\textbf{Burgers}
 , \textbf{Allen–Cahn} and \textbf{Korteweg–De Vries} on the common domain
$(x,t)\in[-1,1]\times[0,1]$.
The interior residual minimised by the PINN is
\[
\mathcal{R}(x,t;\bm{w}) =
\begin{cases}
\partial_t u_\theta + u_\theta\,\partial_x u_\theta - \nu\,\partial_{xx} u_\theta,
  &\text{Burgers},\\[6pt]
\partial_t u_\theta - \epsilon\,\partial_{xx} u_\theta - f(u_\theta),
  &\text{Allen--Cahn},\\[6pt]
\partial_t u_\theta + u_\theta\,\partial_x u_\theta + \mu\,\partial_{xxx} u_\theta,
  &\text{Korteweg--de Vries (KdV)}.
\end{cases}
\]

\paragraph{Optimizer benchmark:} Standard Adam, the second-order SOAP, and PDE-aware Optimizer
\paragraph{Model:} A single MLP: input $(x,t)\in\mathbb{R}^2$; hidden $3\times64$ \texttt{tanh} layers; output $u_\theta(x,t)\in\mathbb{R}$

\paragraph{Collocation sampling.}
We generate training data as follows:
\begin{itemize}[leftmargin=*]
  \item \textbf{Interior (PDE residual):} $N_{\text{int}} = 10{,}000$ collocation points sampled uniformly over the spatio-temporal domain $(x, t) \in [x_{\min}, x_{\max}] \times [t_{\min}, t_{\max}]$.
  \item \textbf{Initial condition:} $N_{\text{ic}} = 1{,}000$ points sampled along $t = t_{\min}$ with $x \in [x_{\min}, x_{\max}]$ evenly spaced.
  \item \textbf{Boundary condition:} $N_{\text{bc}} = 1{,}000$ points sampled with $t \in [t_{\min}, t_{\max}]$, and $x = x_{\min}$ or $x = x_{\max}$ fixed on either boundary.
\end{itemize}

\paragraph{Training:}
\textbf{Batch size} $B = 1{,}024$; \textbf{epochs} $T = 10{,}000$.


\paragraph{Evaluation Metric:}
Relative $L^{2}$ error on a $400\times400$ grid:
\[
\text{Rel-}L^{2} =
\Bigl(
  \tfrac{\sum (u_\theta-u_{\text{exact}})^2}
        {\sum u_{\text{exact}}^2}
\Bigr)^{1/2}.
\]
\paragraph{Hyper-parameter tuning:}
We carried out a full $2\times2\times2$ grid search over the learning-rate $\eta\!\in\!\{10^{-3},10^{-4}\}$ and moments $\beta_1\!\in\!\{0.9,0.99\}$, $\beta_2\!\in\!\{0.99,0.999\}$ for our PDE-aware optimizer on the 1-D Burgers equation. We chose to begin at the default values of the Adam optimizer and vary the hyperparameters from there. The rationale behind the choice for $\beta_2$ was to increase $1-\beta_2$ since that term would determine how much the corresponding residual term would be weighted in $v_t$.
Figure \ref{fig:hyper-tuning} visualizes the validation loss surface for the eight configurations.  
The best setting—$\eta=10^{-3},\;\beta_1=0.99,\;\beta_2=0.99$—achieved an average validation loss of $4.32\times10^{-2}$, with the two closest neighbors ($\eta=10^{-3},\beta_1=0.99,\beta_2=0.999$ and $\eta=10^{-3},\beta_1=0.9,\beta_2=0.99$) trailing by less than $3\times10^{-4}$. 


