A graph $G=(V,E)$ is said to be \emph{bipartite} if $V(G)$ can be partitioned into two independent sets $X$ and $Y$. A graph is a \emph{permutation graph} if and only if it has an intersection model consisting of straight lines (one per vertex) between two parallel lines. A graph that is both a bipartite and permutation graph is called a \emph{bipartite permutation} graph.

A graph $G=(V,E)$ is said to be \emph{chordal}, if there does not exist any induced cycle of length at least $4$ in $G$.  $G$ is \emph{strongly chordal} if it is a chordal graph and every cycle of even length (at least $6$) in $G$ has an odd chord, that is, an edge that connects two vertices which are an odd distance ($>1$) apart from each other in the cycle.

\emph{Distance-hereditary} graphs are graphs in which the distance between any two vertices in any connected induced subgraph is the same as their distance in the original graph.


\subsection{Results from previous literature}
The following results are from the existing literature on the problem and are used in the upcoming proofs.

\begin{theorem}[\cite{DBLP:conf/caldam/FoucaudMMSST24}]\label{th:mandatory}
    Given a graph $G=(V,E)$ and a vertex $v\in V$, $v$ is a mandatory vertex of $G$ if and only if there exists $u\in N(v)$ such that every induced $2$-path $uvx$ is part of a $4$-cycle.
\end{theorem}

\noindent We also propose the following observation, which follows directly from Theorem~\ref{th:mandatory}.

\begin{obs}\label{observation:1}
    Let $u,v\in V$, if $N_G(u)\subseteq N_G(v)$ or $N_G[u]\subseteq N_G[v]$, then $u\in M$, for every MEG set $M$ of $G$. In particular, every simplicial vertex is a mandatory vertex.
\end{obs}

\noindent The next theorem is a corollary of the Theorem \ref{th:mandatory}.

\begin{theorem}[\cite{DBLP:journals/corr/abs-2210.03774,DBLP:conf/caldam/FoucaudNS23}]\label{th:man_twin}
    Given a graph $G=(V,E)$, if two vertices $u$ and $v$ are twins %(meaning $N(u)=N(v)$ or $N[u]=N[v]$)
    of degree at least $1$ in a graph $G$, then they both are mandatory vertices of $G$.
\end{theorem}

\begin{theorem}[\cite{DBLP:conf/caldam/FoucaudMMSST24}]\label{th:man_pendant}
    Let $G=(V,E)$ be a graph with a path $v_0v_1\ldots v_{k-1}v_k$ whose internal vertices have degree $2$, $v_0$ has degree at least $2$, and $v_k$ has degree $1$. Then the vertices $v_0, v_1,\ldots, v_{k-1}$ are never part of any minimum-size MEG set.
\end{theorem}

\begin{theorem}[\cite{DBLP:journals/corr/abs-2210.03774,DBLP:conf/caldam/FoucaudNS23}]\label{th:cut}
    Let $G$ be a graph with a cut-vertex $v$ and $C_1, C_2,\ldots , C_k$ be the $k$ components obtained when removing $v$ from $G$. If $S_1,S_2,\ldots, S_k$ are MEG sets of the induced subgraphs $G[C_1 \cup \{v\}],~G[C_2 \cup \{v\}],\ldots, G[C_k \cup \{v\}]$, then $S=(S_1 \cup S_2\cup \ldots S_k) \setminus \{v\}$ is an MEG set of G.
\end{theorem}




\section{MEG for distance-hereditary graphs}
\label{sec:distance-hereditary}
In this section, we show that the MIN-MEG problem can be solved efficiently for distance-hereditary graphs. Throughout this section, we assume that $G=(V,E)$ is a connected distance-hereditary graph.

For any given ordering
$(v_1, v_2,\ldots,v_n)$ of $V$, let $G_i$ be the graph induced on $\{v_1, v_2,\ldots,v_i\}$. A \emph{one vertex-extension ordering} of G is an ordering $(v_1, v_2,\ldots,v_n)$ of $V$ such that $v_i$ is a leaf or a twin (true or false) of some vertex in $G_i$ for each $i$, $2 \leq i \leq n$. Hammer et al. \cite{DBLP:journals/dam/HammerM90} proved that a graph is distance-hereditary if and only if it has a one-vertex-extension
ordering. We show that for a distance-hereditary graph $G$, $V\setminus Cut(G)$ forms a minimum MEG set of $G$.

\begin{theorem}
    Given a connected distance-hereditary graph $G = (V, E)$, $Man(G)=V \setminus Cut(G)$ and thus, this set is a minimum MEG set of $G$, that can be computed in polynomial time.
\end{theorem}

\begin{proof}
    Our objective is to prove that every vertex $v\in V\setminus Cut(G)$ is mandatory in $G$. To prove this, we employ induction on $\vert V\vert$. The base case, $\vert V\vert=3$, holds true, as the only connected distance-hereditary graphs of order $3$ are $P_3$ and $C_3$, for both of them, $V\setminus Cut(G)= Man(G)$. Now let us assume that every $v\in V\setminus Cut(G)$ is contained in $Man(G)$, whenever $\vert V\vert\leq k$. 

    Let us consider a connected distance-hereditary graph $G=(V,E)$ with $\vert V\vert=k+1$, adhering to a one-vertex extension ordering $(v_1,v_2,\ldots,v_k,v_{k+1})$. As per the definition of a one-vertex extension ordering, $G$ is constructed from $G_k$ by appending $v_{k+1}$ as either a pendant or a twin (true or false) to some $v_j$, where $j\leq k$. We inspect two potential scenarios:

    \noindent\textbf{Case 1}: \textbf{$v_{k+1}$ is a true twin (or false twin) of $v_j$} (refer to Figure \ref{fig:true_twin}). 

    \begin{figure}[h!]
        \centering
        \includegraphics[scale=0.5]{Distance_H_true.eps}
        \caption{The mandatory vertices in $V(G_k)\setminus Cut(G_k)$ remain mandatory in $V(G)\setminus Cut(G)$}
        \label{fig:true_twin}
    \end{figure}

    \noindent Note that $Cut(G)=Cut(G_k)\setminus \{v_j\}$ and $V(G)\setminus Cut(G)=(V(G_k)\setminus Cut(G_k))\cup\{v_j,v_{k+1}\}$. We show that the set $V(G)\setminus Cut(G)$ is contained in every MEG set of $G$. Since $v_j,v_{k+1}$ are twins, they are contained in every MEG set of $G$, by Theorem \ref{th:man_twin}. Hence, $v_j,v_{k+1}\in Man(G)$. 

    \smallskip
    \noindent By the induction hypothesis, the set $V(G_k)\setminus Cut(G_k)$ is contained in every MEG set of $G_k$. This implies that for any $v\in V(G_k)\setminus Cut(G_k)$, there exists $u_v \in N_{G_k}(v)$ such that any induced $2$-path $u_vvx$ is part of a $4$-cycle in $G_k$. Next, we show that $v\in Man(G)$. For the sake of contradiction, assume $v\notin Man(G)$; this implies that there exists an induced $2$-path $u_vvx$ that is part of no $4$-cycle in $G$. But this implies that this $2$-path was not present in $G_k$ (the path highlighted in blue in Figure \ref{fig:true_twin}). Hence, $x=v_{k+1}$. This implies that $v\in N(v_{k+1})$ and $u_v\in N(v)\setminus N(v_{k+1})$; hence $v\in N(v_{k+1})\setminus\{v_j\}$. But note that $v$ was mandatory in $G_k$, which implies $u_vvv_j$ is part of a $4$-cycle $u_vvv_jx'$ in $G_k$ (refer to Figure \ref{fig:true_twin}). This implies $u_vvv_{k+1}$ is also part of the $4$-cycle $u_vvv_{k+1}x'$ in $G$, leading to a contradiction. Hence, $v\in Man(G)$. 


     \smallskip
    \noindent Hence, following the addition of the true twin $v_{k+1}$ with $v_j$ in $G_{k}$, the vertices in $V(G_k)\setminus Cut(G_k)$, which possess the aforementioned property in $G_k$, retain said property in $G$. Hence, every vertex of $V(G)\setminus Cut(G)$ is contained in  $Man(G)$. Note that the proof of the case when $v_{k+1}$ is a false twin of $v_j$, is exactly analogous, hence omitted.


    \medskip
    \noindent\textbf{Case 2}: \textbf{$v_{k+1}$ is a pendant vertex adjacent to $v_j$}.

    \smallskip
    \noindent Note that $Cut(G)=Cut(G_k)\cup \{v_j\}$. Since $v_{k+1}$ is a pendant vertex, it is contained in $Man(G)$, by Theorem \ref{th:man_pendant}. By the induction hypothesis, $V(G_k)\setminus Cut(G_k)$ is contained in every MEG set of $G_k$. This implies that for every $v\in V(G_k)\setminus (Cut(G_k)\cup \{v_j\})$, there exists $u_v \in N(v)$ such that any induced $2$-path $u_vvx$ is part of a $4$-cycle. Hence, after the pendant addition of $v_{k+1}$ with $v_j$, the vertices in $V(G_k)\setminus (Cut(G_k)\cup \{v_j\})$, which holds the above property in $G_k$ also hold the property in $G$. This implies that $V(G)\setminus Cut(G)$ is contained in every MEG set of $G$.

    \medskip
    \noindent Hence, by induction, we have shown that $V\setminus Cut(G) \subseteq Man(G)$. Hence, $V\setminus Cut(G) = Man(G)$ and $V\setminus Cut(G)$ is a minimum MEG set of $G$.
\end{proof}

\section{MEG for $P_4$-sparse graphs}\label{sec:P4sparse}
In this section, we propose an efficient algorithm that solves the MIN-MEG problem for $P_4$-sparse graphs. The class of $P_4$-sparse graphs is an extension of the class of cographs. Below, we state a characterization theorem for $P_4$-sparse graphs from the previous literature.

\begin{theorem}[\cite{Defn_P4sparse}]\label{th:5}
    A graph $G$ is said to be $P_4$-sparse if and only if one of the following conditions hold
    \begin{itemize}
        \item $G$ is a single vertex graph.
        \item $G=G_1\cup G_2$, where $G_1$ and $G_2$ are $P_4$-sparse graphs.
        \item $G=G_1 \oplus G_2$, where $G_1$ and $G_2$ are $P_4$-sparse graphs.
        \item $G$ is a spider which admits a spider partition $(S, C, R)$ where either $G[R]$ is a $P_4$-sparse graph or $R=\emptyset$.
    \end{itemize} 
\end{theorem}

Hence, by Theorem \ref{th:5}, a graph that is $P_4$-sparse and contains at least two vertices can be classified as either a join or union of two $P_4$-sparse graphs or a particular type of spider (thick or thin). Consequently, in this section, we compute $meg(G)$ for each of the cases. First, we consider the case of $G$ being a spider.

\begin{lemma}\label{lem:thin}
    Let $G=(V,E)$ be a thin spider and $(S,C,R)$ be the spider partition. Then, $Man(G)=S\cup R$, which is an optimal MEG set of $G$.
\end{lemma}

\begin{proof}
    Note that by Observation \ref{observation:1}, $S$ is contained in every MEG set (as every vertex of $S$ is a pendant vertex) and no vertex in $C$ can be part of a minimum MEG set, as they are cut-vertices. Now if $R\neq \emptyset$, then for each $r\in R$ and for any $c\in C$, $N[r]\subset N[c]$, hence by Observation \ref{observation:1}, $r$ is contained in every MEG set. Hence $meg(G)=\vert Man(G)\vert=\vert S\vert+\vert R\vert$.
\end{proof}

\begin{lemma}\label{lem:thick}
    Let $G=(V,E)$ be a thick spider and $(S,C,R)$ be the spider partition. Then, $meg(G)=\vert S\vert+\vert R\vert$, if $\vert C\vert=2$ and $meg(G)=\vert Man(G)\vert =\vert V\vert$, otherwise.
\end{lemma}

\begin{proof}
    Note that if $\vert C\vert=2$, then $G$ is a thin spider; hence, the result follows from the previous lemma. Now, let $\vert C\vert\geq 3$. Consider any two distinct vertices $c_i,c_j$ from $C$. The only induced $2$-path of type $c_jc_ix$ is $c_jc_is_j$, which is part of a $4$-cycle $c_jc_is_jc_k$, where $k\notin\{i,j\}$; such $k$ exists as $\vert C\vert\geq 3$. This implies that $c_i$ is a mandatory vertex for every $c_i\in C$. Now if $R\neq \emptyset$, then for any $r\in R$ (or $s\in S$), $N[r]\subset N[c]$ (or $N[s]\subset N[c]$), for any $c\in C$. Hence, by Observation \ref{observation:1}, $R\cup S$ is contained in every MEG set. Hence $meg(G)=\vert V\vert=\vert Man(G)\vert$.
\end{proof}

Now, the only case that remains to be seen is when $G$ is a join of two $P_4$-sparse graphs $G_1$ and $G_2$. Note that if $G_1$ and $G_2$ both are nontrivial graphs (having more than one vertex), then $meg(G)=\vert V(G)\vert$. Now assume that, without loss of generality, $\vert V(G_1)\vert=1$ and $V(G_1)=\{v\}$. Two cases can appear. In the first case, if $G_2$ is a disconnected graph, then $v$ is a cut-vertex and $N[x]\subseteq N[v]$ for any $x\in V(G_2)$, hence $meg(G)=\vert V(G_2)\vert$. For the other case, let $G_2$ be a connected graph. In that case, we propose the following lemma.

\begin{lemma}\label{lem:join}
    Let $G=G_1\oplus G_2$ and $V(G_1)=\{v\}$ and $G_2$ is a non trivial connected $P_4$-sparse graph. Then, 
    \begin{enumerate}
        \item $meg(G)=n$, if there exists a vertex $u$ in $G_2$, which satisfies the property that $d_{G_2}(u,x)\leq 2$ for every $x\in V(G_2)\setminus\{u\}$.
        \item $meg(G)=n-1$, otherwise.
    \end{enumerate}  
\end{lemma}

\begin{proof}
    Note that for every vertex $x\in V(G_2)$, $N[x]\subseteq N[v]$. Hence $x$ belongs to every MEG set of $G$, implying $V(G_2)\subseteq M$, where $M$ is any minimum MEG set of $G$. Suppose there exists a vertex $u\in V(G_2)$, with the property: $d_{G_2}(u,x)\leq 2$ for every $x\in X$. Now consider any induced $2$-path $uvy$. Clearly, $u,y$ are not adjacent. Hence $d_{G_2}(u,y)=2$. So, $uvy$ is part of a $4$-cycle, as $y$ is at distance $2$ from $u$ in the graph $G_2$. Hence, by Theorem \ref{th:mandatory}, $v$ is a mandatory vertex in $G$, for every $v\in V(G)$; which implies that $meg(G)=n$.

    Now, let us assume that no such vertex $u$ exists. Consider any edge $vx$, $x\in V(G_2)$. By the assumption there exists a vertex $x'\in V(G_2)$ such that $d_{G_2}(x,x')\geq 3$. Hence, the pair $x,x'$ monitors the edge $vx$. Since $x$ is arbitrary in $G_2$, then every edge of the form $vx$ can be monitored by some pair of vertices in $G_2$. Hence, $meg(G)=n-1$. 
\end{proof}


Hence, from the above discussion and Lemma \ref{lem:thin}, \ref{lem:thick}, \ref{lem:join} the following theorem can be concluded:

\begin{theorem}\label{th:p4}
    Given a connected $P_4$-sparse graph $G=(V,E)$, $meg(G)=\vert Man(G)\vert$ and thus, this set is a minimum MEG set of $G$, that can be computed in polynomial time.
\end{theorem}

\section{MEG for bipartite permutation graphs}
\label{sec:bip_per}
A \emph{strong ordering} $(<_X, <_Y)$ of a bipartite graph $G = (X\cup Y, E)$ entails an ordering $<_X$ for the set $X$ and an ordering $<_Y$ for the set $Y$. This ordering adheres to the condition that for any edges $ab$ and $a_0b_0$, where $a, a_0 \in X$ and $b, b_0 \in Y$, if $a$ precedes $a_0$ in $<_X$ and $b_0$ precedes $b$ in $<_Y$, then both $ab_0$ and $a_0b$ are edges in $G$. An ordering $<_X$ for $X$ exhibits the \emph{adjacency property} if, for each vertex in $Y$, its neighbours in $X$ appear consecutively in $<_X$. Moreover, the ordering $<_X$ is said to have the \emph{enclosure property} if, for any pair of vertices $y$ and $y_0$ in $Y$ where $N(y)$ is contained in $N(y_0)$, the vertices of $N(y_0) \setminus N(y)$ are consecutive in $<_X$. Strong ordering, adjacency property, and enclosure property, as delineated above, yield the subsequent result as discussed in previous literature.

\begin{theorem}[\cite{DBLP:journals/dam/SpinradBS87}]\label{th:bip_perm}
    The following statements are equivalent for a graph $G =(X\cup Y, E)$.
\begin{enumerate}
    \item $G = (X\cup Y, E)$ is a bipartite permutation graph.
    \item  $G$ has a strong ordering.
    \item There exists an ordering of X, which has the adjacency property and the
enclosure property.
\end{enumerate}

\end{theorem}

Hence, from Theorem \ref{th:bip_perm}, we can conclude that if $G$ is a bipartite permutation graph, then $G$ has a strong ordering. We state another result from the previous literature.


\begin{theorem}[\cite{DBLP:journals/siamdm/HeggernesHLN12}]
    Let $(<_X, <_Y )$ be a strong ordering of a connected bipartite
permutation graph $G = (X\cup Y, E)$. Then both $<_X$ and $<_Y$ have the adjacency property and the enclosure property.
\end{theorem}

Hence, given a bipartite graph $G=(X\cup Y,E)$, with its strong ordering $(<_X,<_Y)$, the following notations can be defined:
\begin{itemize}
    \item $f(v)=v'$, where $v'\in N(v)$ and $v'< u$ for every $u\in N(v)$
    \item $l(v)=v'$, where $v'\in N(v)$ and $u< v'$ for every $u\in N(v)$.
\end{itemize}


In the above definition of $f$ and $l$, the notation $<$ is used for both $<_X$ and $<_Y$. Note that the ordering $(<_X,<_Y)$ has the following properties (see \cite{LAI199733}):

\begin{enumerate}
    \item Given any vertex of $G$, its neighbor set consists of some consecutive vertices in $<_X$ or $<_Y$.
    \item For a pair of vertices $u, v$ from $X$ or $Y$, if $u < v$ then $f(u) \leq f(v)$ and $l(u) \leq l(v)$.
\end{enumerate}

Throughout this section, we assume that $G=(X\cup Y,E)$ is a bipartite permutation graph. Given a strong ordering $(<_X,<_Y)$ of $G$, let the vertices of $X$ and $Y$ be ordered as $x_1<_X x_2<_X\ldots x_p$ and $y_1<_Y y_2<_Y\ldots y_q$, where $p=\vert X\vert$ and $q=\vert Y\vert$. When the context is clear, we write $<$ instead of $<_X$ or $<_Y$. In this section we call $x_1,x_p,y_1,y_q$ as \emph{extreme} vertices and all the other vertices as \emph{interim} vertices.

\begin{lemma}\label{lem:bip_per}
    Given a connected bipartite permutation graph $G=(X\cup Y,E)$ with strong ordering $(<_X,<_Y)$ and an interim vertex $u\in V(G)$, $u$ is not a cut-vertex if and only if there exists $u_0\in N(u)$ such that $f(u_0)<u$ and $l(u_0)>u$.
\end{lemma}


\begin{proof}
    Without loss of generality, let $u\in X$ and $u=x_i$. Let there exists $u_0\in Y$ such that $f(u_0)<u$ and $l(u_0)>u$. For the sake of contradiction, assume that $u$ is a cut-vertex. Let $X_i=\{x_1,\ldots,x_{i-1}\}$ and $X_i'=\{x_{i+1},\ldots, x_p\}$. In the next claim, we show that both the graphs $G[X_i\cup N(X_i)]$ and $G[X_i'\cup N(X_i')]$ are connected. 
    \begin{claim}
         $G[X_i\cup N(X_i)]$ and $G[X_i'\cup N(X_i')]$ are connected. 
    \end{claim}

    \begin{proof}
        For the sake of contradiction, let there exists $x_j\in X_i$ such that $N(x_j)\cap N(x_{j+1})=\emptyset$. This implies that $l(x_j)<f(x_{j+1})$, hence $l(x_j)<f(x_{k})$ for all $k\in \{j+1,\ldots,p\}$. Hence, $N(x_j)\cap N(x_k)=\emptyset$, for all $k\in \{j+1,\ldots,p\}$. This implies that there does not exist any path from $x_j$ to $x_{j+1}$ in $G$, which contradicts the fact that $G$ is a connected graph. Hence, $N(x_j)\cap N(x_{j+1})\neq \emptyset$, for all $j\in \{1,\ldots,i-1\}$. This implies that $G[X_i\cup N(X_i)]$ is connected. Analogously, it can be shown that $G[X_i'\cup N(X_i')]$ is also connected.
    \end{proof}

    Since $u_0\in N(X_i)\cap N(X_i')$, $G[X_i\cup N(X_i)\cup X_i'\cup N(X_i')]$ is also connected (refer to Figure \ref{fig:bip_per} for better understanding). Hence $G\setminus \{u\}=G[(X_i\cup N(X_i)\cup X_i'\cup N(X_i'))]$ is a connected graph, which implies that $u$ is not a cut-vertex. If $u\in Y$, the proof follows from similar arguments.

