        \centering
         \includegraphics[scale=0.4]{Bip_per.eps}
        \caption{$u=x_i$ is not a cut-vertex}
        \label{fig:bip_per}
    \end{subfigure}
\hspace{0.5in}
    \begin{subfigure}{0.4\textwidth}
    \centering
         \includegraphics[scale=0.4]{bip_per_2.eps}
        \caption{$u=x_i$ is not a cut-vertex}
        \label{fig:bip_per_2}
    \end{subfigure}
