\label{pendant_2}
\end{figure}




    Conversely, assume that $u$ is not a cut-vertex. For the sake of contradiction, assume that for every $y_j\in N(x_i)$, either $f(y_j)=x_i$ or $l(y_j)=x_i$. Hence, $N(x_i)$ can be partitioned into two sets $Y_f=\{y\in N(x_i)~\vert~f(y)=x_i\}$ and $Y_l=\{y\in N(x_i)~\vert~l(y)=x_i\}$. Note that none of the set $Y_f$ and $Y_l$ can be empty as $x_i$ is an interim vertex and $G$ is a connected graph. Consider any two vertices, $y\in Y_f$ and $y'\in Y_l$. Note that every $y-y'$ path contains $x_i$ (refer to Figure \ref{fig:bip_per_2}). Hence, $G\setminus\{x_i\}$ is disconnected, which leads to a contradiction. Hence there exists a vertex $u_0\in N(u)$ such that $f(u_0)<u$ and $l(u_0)>u$.
 \end{proof}

    \begin{theorem}\label{lem:bip_per_2}
       Given a connected bipartite permutation graph $G = (X\cup Y, E)$, $Man(G) =V \setminus Cut(G)$ and thus, this set is a minimum MEG set of G, that can be computed in polynomial time.
    \end{theorem}

    \begin{proof}
        We show that every non-cut-vertex is a mandatory vertex. Note that if an extreme vertex $u\in V(G)$ is not a cut-vertex, then it is either a pendant vertex or there exists $u'$ such that $N(u)\subseteq N(u')$. In both cases, $u$ is a mandatory vertex.

        \smallskip
        \noindent Now, we consider an interim vertex $x_i\in X$ (without loss of generality), which is not a cut-vertex. By Lemma \ref{lem:bip_per}, there exists $y_j\in N(x_i)$ such that $f(y_j)<x_i$ and $l(y_j)>x_i$. Note that for any induced $2$-path $y_jx_iy_k$, two cases can occur.

        \smallskip
        \noindent\textbf{Case 1}: $y_k<y_j$. In this case $x_{i-1}\in N(y_k)\cap N(y_j)$. This implies that $y_jx_iy_k$ is part of a $4$-cycle $y_jx_iy_kx_{i-1}y_j$.

        \smallskip
        \noindent\textbf{Case 2}: $y_k>y_j$. In this case $x_{i+1}\in N(y_k)\cap N(y_j)$. This implies that $y_jx_iy_k$ is part of a $4$-cycle $y_jx_iy_kx_{i+1}y_j$.

        \smallskip
        \noindent Hence $x_i$ is a mandatory vertex, by Theorem \ref{th:mandatory}. The same can be shown for an interim vertex $y_i\in Y$ which is not a cut-vertex. Hence $Man(G)=V(G)\setminus Cut(G)$.
    \end{proof}

\section{MEG for strongly chordal graphs}
\label{sec:strong_chordal}
In this section, we consider that $G=(V,E)$ is a strongly chordal graph. We use the definition of strongly chordal graphs defined in \cite{DBLP:journals/dam/Farber84}. We define a vertex $v \in V$ as \emph{simple} if the vertices within its closed neighborhood can be arranged as follows: $N_G[v] = {v_1, v_2, \ldots , v_r}$, where $v_1 = v$ and $N_G[v_i] \subseteq N_G[v_j]$ for $1 \leq i \leq j \leq r$. A graph $G$ is strongly chordal if every induced subgraph of $G$ contains a simple vertex. An ordering $\alpha = (v_1, v_2,\ldots, v_n)$ of vertices in $V$ is called a strong elimination ordering (SEO) if $v_i$ is a simple vertex in $G[v_i,v_{i+1},\ldots,v_n]$. A graph is strongly chordal if it admits an SEO. We show that the set of mandatory vertices forms an MEG set for all strongly chordal graphs.

\begin{theorem}
	For any strongly chordal graph $G$, $Man(G)$ forms an optimal MEG set of $G$, and thus MEG can be solved in polynomial time for this class of graphs.
\end{theorem}

\begin{proof} 
	We show this by induction on the number of vertices in the graph, $n$. For $n=3$, the strongly chordal graphs are $P_3$ and $C_3$; the statement is true for both of these graphs. Hence, the statement is true for base cases. Now, let the statement be true for $n=k$. For $n=k+1$, let us consider a strongly chordal graph $G_{k+1}$ with SEO $v_1<v_2<\ldots<v_{k+1}$. Now define $G_k:=G_{k+1}[v_2,v_3,\ldots,v_{k+1}]$. Let us consider the neighbourhood of $v_1$ as $N(v_1)=\{v_{i_1},v_{i_2},\ldots,v_{i_l}\}$, where $N[v_{i_1}]\subseteq N[v_{i_2}]\subseteq\ldots \subseteq N[v_{i_l}]$. First, we show the following claims.

	\begin{claim}\label{Claim_5.1}
		$Man(G_{k})\setminus \{v_{i_l}\}\subseteq Man(G_{k+1})\subseteq Man(G_k)\cup\{v_1,v_{i_l}\}$.
	\end{claim}

	\begin{proof}
		Note that by Observation~\ref{observation:1},  $N[v_1]\setminus \{v_{i_l}\}\subseteq Man(G_{k+1})$ as for every $v\in N[v_1]\setminus \{v_{i_l}\}$, $N[v]\subseteq N[v_{i_l}]$. Now, $V(G_{k+1})$ can be partitioned as $V(G_{k+1})=N[v_1]\cup V'$, where $V'$ is the set of all non neighbours of $v_1$. Let us consider a vertex $v\in V'$. Two cases can appear.

	\smallskip
    \noindent \textbf{Case 5.1.1}: $v\in Man(G_k)$

    \smallskip
    \noindent This implies that a vertex $u\in N_{G_k}(v)$ exists such that every induced $2$-path $uvx$ is part of a $4$-cycle. Now, after adding $v_1$ to the vertex set, the neighbour set of $v$ has not expanded, as $v$ is not a neighbour of $v_1$. This implies that every induced $2$-path $uvx$ is still part of a $4$-cycle. This implies $v\in Man(G_{k+1})$. 

	\smallskip
    \noindent \textbf{Case 5.1.2}: $v\notin Man(G_k)$ 

    \smallskip
    \noindent For the sake of contradiction, let $v \in Man(G_{k+1})$. This implies that there exists $u\in N_{G_{k+1}}(v)$ such that every induced $2$-path $uvx$ is part of a $4$-cycle $uvxx'$. Note that $u\neq v_1$, as $v$ is not adjacent to $v_1$. But since $v$ was not a mandatory vertex in $G_k$, for this $u$, there must exist an induced $2$-path $uvx$ in $G_k$, which is not part of any $4$-cycle in $G_k$. This implies that the $4$-cycle $uvxx'$ in $G_{k+1}$, of which $uvx$ is part of, must include $v_1$. This implies that $x'=v_1$ and $u,x\in N(v_1)$. Hence, there is an edge between $u$ and $x$ (refer to Figure \ref{fig:claim1.1}), as the graph induced on $N[v_1]$ is a clique. So, $uvx$ is not an induced $2$-path, which leads to a contradiction. Hence,  $v \notin Man(G_{k+1})$.

      \begin{figure}[h!]
        \centering
        \includegraphics[scale=0.45]{Claim1_1.eps}
        \caption{$v$ is a mandatory in $G_{k+1}$ but not in $G_k$}
        \label{fig:claim1.1}
    \end{figure}

	This implies $Man(G_k)\cap V'=Man(G_{k+1})\cap V'$ and $N(v_1)\setminus\{v_{i_l}\} \subseteq Man(G_k)$ and $N[v_1]\setminus\{v_{i_l}\} \subseteq Man(G_{k+1})$. Hence, the claim follows.
	\end{proof}


\begin{claim}
    If $v_1$ is a pendant vertex, then $Man(G_{k+1})$ is an optimal MEG set of $G$.
\end{claim}
\begin{proof}
    Note that if $v_1$ is a pendant vertex in $G_{k+1}$, then $N(v_1)=\{v_{i_1}\}$. This implies that $Man(G_{k+1})=(Man(G_k)\setminus\{v_{i_1}\})\cup \{v_1\}$. By the induction hypothesis, $Man(G_k)$ is an MEG set of $G_k$. If $v_{i_1}\in Man(G_k)$, then there exists an edge $uv \in E(G_k)$ that is only being monitored by $v_{i_1}$ and $v'$ for some $v'\in Man(G_k)$; such that no other pair in $Man(G_k)$ monitors $uv$. Evidently, $uv$ and $v_1v_{i_1}$ can both be monitored by $v_1,v'$ in $G_{k+1}$ (refer to Figure \ref{pendant_1}).

