    \centering
    \begin{subfigure}{0.4\textwidth}
        \centering
        \includegraphics[width=1\linewidth]{Pendant_1.eps}
    \caption{The pair $v_1,v'$ monitors both the edge $v_1v_{i_1}$ and $uv$}
    \label{pendant_1}
    \end{subfigure}
\hspace{0.5in}
    \begin{subfigure}{0.36\textwidth}
    \centering
        \includegraphics[width=1\linewidth]{Pendant_2.eps}
    \caption{The pairs $v_1,a$ and $v_1,b$ both monitors the edge $v_{i_1}v_1$}
    \label{subfig:2}
    \end{subfigure}
    \caption{$v_1$ is a pendant vertex and $v_{i_1}$ is the stem}
%\label{pendant_2}
\end{figure}

     If $v_{i_1}\notin Man(G_k)$, then all the edges in $G_{k+1}$ except $v_1v_{i_1}$ are being monitored by some pair of vertices in $Man(G_k)$. The only edge that remains to be monitored is $v_1v_{i_1}$. Consider any edge of the form $v_{i_1}x$ in $G_k$. It is monitored by some $a,b\in Man(G_k)$. Hence, it is not hard to see that either the pair $a,v_1$ or the pair $b,v_1$ monitors the edge $v_1v_{i_1}$ (refer to Figure \ref{subfig:2}). Hence in both of the cases, $meg(G_{k+1})=\vert Man(G_{k+1})\vert$.
\end{proof}

\medskip
\noindent So, from now on, let us assume that $\vert N_{G_{k+1}}(v_1)\vert\geq 2$, that is $v_1$ is not a pendant vertex in $G_{k+1}$. 

	\begin{claim}\label{Claim_5.2}
		If $v_{i_l}\in Man(G_{k+1})$, then $v_{i_l}\in Man(G_{k})$.
	\end{claim}

	\begin{proof}
	 For the sake of contradiction, let us assume that $v_{i_l}\in Man(G_{k+1})$ but $v_{i_l}\notin Man(G_{k})$. Then for every $u\in N_{G_k}(v_{i_l})$, there exists an induced $2$-path $uv_{i_l}x$ in $G_k$, which is not part of any $4$-cycle in $G_k$. But since, $v_{i_l}\in Man(G_{k+1})$, there exists $u_i\in N_{G_{k+1}}(v_{i_l})$ such that every induced $2$-path $u_iv_{i_l}x$ is part of a $4$-cycle $u_iv_{i_l}xx'$ in $G_{k+1}$. This $4$-cycle was clearly not present in $G_{k}$, which implies that either $u_i=v_1$ or $x'=v_1$. If $u_i=v_1$, then for every neighbour $x$ of $v_{i_l}$, $x$ is also adjacent to a vertex $x'$ in $N(v_1)\setminus \{v_{i_l}\}$ (refer to Figure \ref{fig:claim2.1}). This implies $x\in N[v_{i_{l-1}}]$, hence $N[v_{i_{l-1}}]= N[v_{i_l}]$, which implies that $v_{i_l}\in Man(G_k)$, by Theorem \ref{th:man_twin}, leading to a contradiction. If $x'=v_1$, then $u_i,x\in N(v_1)$. This implies that an edge exists from $u_i$ to $x$, as the graph induced on $N[v_1]$ is a clique, which contradicts the fact that $u_ivx$ is an induced $2$-path. Hence, $v_{i_l}\in Man(G_{k})$.
	\end{proof}

 \begin{figure}[h!]
        \centering
        \includegraphics[scale=0.45]{Claim2_1.eps}
        \caption{$u_i=v_1$ implies that $N[v_{i_{l-1}}]= N[v_{i_l}]$}
        \label{fig:claim2.1}
    \end{figure}

	Claim \ref{Claim_5.2} implies that if the vertex $v_{i_l}$ is mandatory in $G_{k+1}$, then it was also mandatory in $G_k$. Two cases may appear for $v_{i_l}$. The rest of the proof proceeds as follows:
    \begin{itemize}
        \item In Case 1, we consider $v_{i_l}\in Man(G_{k+1})$ and show that $Man(G_{k+1})$ forms an MEG set.
        \item In Case 2, we consider $v_{i_l}\notin Man(G_{k+1})$. Here again, two subcases may appear, $v_{i_l}\notin Man(G_{k})$ (Case 2.1) and $v_{i_l}\in Man(G_{k})$ (Case 2.2). In both of the subcases, we show that $Man(G_{k+1})$ forms an MEG set.
    \end{itemize}

	\noindent \textbf{Case 1}: $v_{i_l}\in Man(G_{k+1})$\\
	By Claim \ref{Claim_5.2}, $v_{i_l}\in Man(G_{k})$. In this case, $Man(G_{k+1})=Man(G_k)\cup\{v_1\}$. Now, by induction hypothesis, $Man(G_k)$ is an MEG set of $G_k$. Next we prove the following claim:
    \begin{claim}
        $v_1$ does not belong to any shortest $x-y$ path, where $x,y\in V(G_k)$.
    \end{claim}

    \begin{proof}
        Clearly, none of the $x,y$ is $v_1$ as they both belong to $V(G_k)$. For the sake of contradiction, let $P=((x=)x_1x_2\ldots x_k(=y))$ is a shortest $x-y$ path which contains $v_1$. Let $x_i=v_1$ for some $1<i<k$. Then the vertices $x_{i-1},~x_{i+1}$ are adjacent in $G_k$ (and in $G_{k+1}$ as well), as $N[v_1]$ induces a clique. This implies that $x_1x_2\ldots x_{i-1}x_{i+1}\ldots x_k$ is a path between $x$ and $y$ which has smaller length than $P$, which contradicts the fact that $P$ is a shortest $x-y$ path. Hence  $v_1$ does not belong to any shortest $x-y$ path.
    \end{proof}

    \medskip
    \noindent Hence, all the edges in $G_{k+1}$ that do not have $v_1$ as an endpoint are being monitored by some pair of vertices in $Man(G_k)$. Now since $N[v_1]\subseteq Man(G_{k+1})$, then all the edges of the form $v_1x$ are being monitored by $v_1$ and $x$, as $x\in N[v_1]\subseteq Man(G_{k+1})$. Hence, $Man(G_{k+1})$ is an MEG set of $G_{k+1}$.

    \medskip
    \noindent \textbf{Case 2}: $v_{i_l}\notin Man(G_{k+1})$\\
In this case, either $v_{i_l}\in Man(G_{k})$ or $v_{i_l}\notin Man(G_{k})$. 

\medskip
\noindent \textbf{Case 2.1}: $v_{i_l}\notin Man(G_{k})$

\smallskip
\noindent If $v_{i_l}\notin Man(G_{k})$, then all the edges in $E(G_{k+1})$ which do not have $v_1$ as an endpoint are monitored by some pair in $Man(G_k)$. All the edges of the form $v_1v_{i_j}$ are monitored by $v_1$, $v_{i_j}$, for every $1\leq j\leq l-1$. Now, the edge that is yet to be monitored is $v_1v_{i_l}$. Note that the edge  $v_{i_{l-1}}v_{i_l}$ is being monitored by $v_{i_{l-1}}$ and $v'$ for some $v'\in Man(G_k)$. This implies that every shortest path between $v_{i_{l-1}}$ and $v'$ contains the edge $v_{i_{l-1}}v_{i_l}$. Hence, every shortest $v_1-v'$ path also contains the edge $v_1v_{i_l}$, if not then there exists a shortest $v_{i_{l-1}}-v'$ path that bypasses the edge $v_{i_{l-1}}v_{i_l}$, which leads to a contradiction (refer to Figure \ref{fig:claim2.2}). Hence, $Man(G_{k+1})$ forms an MEG set of $G_{k+1}$.

 \begin{figure}[h!]
        \centering
        \includegraphics[scale=0.45]{Claim2_2.eps}
        \caption{The pair $v_1, v'$ monitors the edge $v_1v_{i_1}$}
        \label{fig:claim2.2}
    \end{figure}

\noindent \textbf{Case 2.2}: $v_{i_l}\in Man(G_{k})$

   \smallskip
   \noindent Let $v_{i_l}\in Man(G_{k})$. Hence $Man(G_{k+1})=(Man(G_k)\setminus \{v_{i_l}\})\cup \{v_1\}$. Now define $E_l$ as the set of edges in $G_k$ which were only being monitored by $v_{i_l},v'$, for some $v'\in Man(G_k)$ and no other pairs in $Man(G_k)$. Note that every edge in $E(G_{k+1})\setminus E_l$ is being monitored by some pair in $Man(G_{k+1})$. Hence, it is sufficient to prove that every edge in $E_l$ can be monitored by some pair in $Man(G_{k+1})$. Consider an edge $e\in E_l$.

    \medskip
    \noindent \textbf{Case 2.2.1}: $v_{i_l}$ is not an endpoint of $e$.

    \smallskip
    \noindent If $v_{i_l}$ is not an endpoint of $e$, then in $G_k$, $e$ was monitored by $v_{i_l},v'\in Man(G_k)$. Note that $v'\notin N[v_1]$. Every shortest $v_{i_l}-v'$ path contains the edge $e$. Next we show that every shortest $v_1-v'$ path also contains $e$ (refer to Figure \ref{fig:e_non}).

    \begin{claim}
         Every shortest $v_1-v'$ path also contains $e$.
    \end{claim}

    \begin{proof}
        Let there exists a shortest $v_1-v'$ path $P=((v_1=)x_1x_2\ldots x_k(=v'))$ that does not contain $e$. Note that $v_{i_l}$ does not belong to the path (as it will contradict the fact that every shortest $v_{i_l}-v'$-path contains the edge $e$). Without loss of generality, let us assume that $x_2=v_{i_{l-1}}$. Note that $d(v_1,v')=1+d(v_{i_l},v')$, or $v_{i_l}x_2\ldots x_k(=v')$ is a shortest $v_{i_l}-v'$ path that does not contain $e$, leading to a contradiction. This implies that $d(v_{i_l},v')=d(v_{i_{l-1}},v')$. 

         \smallskip
    \noindent Hence, $v_{i_{l-1}}x_3\ldots x_k$ is a shortest $v_{i_{l-1}}-v'$ path that bypasses $e$. Since $N[v_{i_{l-1}}]\subseteq N[v_{i_l}]$, $x_3$ is also adjacent to $v_{i_l}$, hence $v_{i_l}x_3\ldots x_k$ is a shortest $v_{i_l}-v'$ path that avoids $e$, which is a contradiction to the fact that $v_{i_l},v'$ monitor $e$. Hence, every shortest $v_1-v'$ path also contains $e$.     
    \end{proof}

    \begin{figure}[h!]
        \centering
        \includegraphics[scale=0.45]{e_non_incident.eps}
        \caption{$e$ is not incident to $v_{i_l}$}
        \label{fig:e_non}
    \end{figure}


    \noindent \textbf{Case 2.2.2}: $v_{i_l}$ is an endpoint of $e$.

    \smallskip
    \noindent If $v_{i_l}$ is an endpoint of $e$, then let the other endpoint be $v$. Note that in $G_k$, the edge $v_{i_l}v$ was monitored by $v_{i_l}$ and $v'$ for some $v'$. 

    \smallskip
    \noindent At first let us consider the case $v\notin N_{G_{k+1}}(v_{i_{l-1}})$; such $v$ exists as $N[v_{i_{l-1}}]\subset N[v_{i_l}]$ (otherwise $v_{i_{l-1}},~v_{i_l}$ are twins, hence $v_{i_l}$ will be a mandatory vertex of $G_{k+1}$). Now note that $d_{G_{k+1}}(v,v_1)=2$ and $vv_{i_l}v_1$ is the unique shortest path from $v_1$ to $v$. Hence, the edge $v_{i_l}v$ is contained in every shortest $v_1-v'$ path (refer to Figure \ref{fig:claim_1_unotin}). Note that the edges $v_1v_{i_l}$ and $v_{i_{l-1}}v_{i_l}$ are also monitored by the pairs $v_1,v'$ and $v_{i_{l-1}},v'$, respectively.

    \begin{figure}[h!]
        \centering
        \includegraphics[scale= 0.45]{Claim_1_unotin.eps}
        \caption{$v_{i_l}v$ is being monitored by $v_1$ and $v'$}
        \label{fig:claim_1_unotin}
    \end{figure}


    \smallskip
    \noindent Let $v\in N_{G_{k+1}}(v_{i_{l-1}})$. Note that there exists $x\in N[v_{i_{l}}]\setminus N[v_{i_{l-1}}]$ such that the induced $2$-path $vv_{i_l}x$ is part of no $4$-cycle. If not, then by Theorem \ref{th:mandatory} $v_{i_l}$ would be mandatory in $G_{k+1}$ as well. Now the edges $v_{i_l}v$ and $v_{i_l}x$ are being monitored by $v_{i_l},v'$ and $v_{i_l},x'$, respectively in $G_k$ (refer to Figure \ref{fig:claim_1_unotin_1}). We also consider $v'$ (and $x'$) to be the minimum distance mandatory vertex from $v_{i_l}$ such that $v_{i_l}$ and $v'$ ($v_{i_l}$ and $x'$) monitor the edge $v_{i_l}v$ ($v_{i_l}x$). Note that $v'\neq x'$; since if $v'=x'$, then every shortest $v_{i_l}-v'$ path contains both of the edges $v_{i_l}v$ and $v_{i_l}x$, which is a contradiction. 

      \begin{figure}[h!]
        \centering
        \includegraphics[scale=0.45]{Claim_1_unotin_1.eps}
        \caption{$e$ is incident to $v_{l_1}$}
        \label{fig:claim_1_unotin_1}
    \end{figure}

    \smallskip
    \noindent We show that $v',x'$ monitor the edge $v_{i_l}v$ in $G_{k+1}$. Now, for the sake of contradiction, assume that there exists a shortest $v'-x'$ path $P$ that bypasses the edge $v_{i_l}v$ (refer to Figure \ref{fig:main_proof_1}). 



    \begin{figure}[h!]
    \centering
    \begin{subfigure}{0.41\textwidth}
        \centering
        \includegraphics[width=1\linewidth]{Main_proof_1.eps}
    \caption{Another shortest path $P$ from $v'$ to $x'$}
    \label{fig:main_proof_1}
    \end{subfigure}
\hspace{0.5in}
    \begin{subfigure}{0.41\textwidth}
    \centering
        \includegraphics[width=1\linewidth]{Main_proof_2.eps}
    \caption{$v_{i_l}$ is incident to exactly one chord in $C$}
    \label{fig:main_proof_2}
    \end{subfigure}
    \caption{The cycle $C$ created by two distinct paths from $v'$ to $x'$}
%\label{pendant_2}
\end{figure}

    \smallskip
    \noindent Let $v_1'$ (and $x_1'$) be the nearest vertex form $v_{i_l}$ that is present in $P\cap P_{v_{i_l}v'}$ (and $P\cap P_{v_{i_l}x'}$) (refer to Figure \ref{fig:main_proof_1}), where $P_{a,b}$ is defined to be any shortest $a-b$ path. Since $P$ is a shortest path from $v'$ to $x'$, then $d_P(v'_1,x'_1)\leq d(v'_1,v_{i_l})+d(x'_1,v_{i_l})$. Let $C$ be the cycle which is constructed with the boundaries $P(v'_1,x'_1)$, $P_{x'_1v_{i_l}}$ and $P_{v_{i_l}v'_1}$ (Refer to Figure \ref{fig:main_proof_1}). Note that there must be at least one chord attached to $v_{i_l}$ in the cycle $C$. If not, since $vv_{i_l}x$ form an induced 2-path, then $vv_{i_l}x$ is part of a cycle of length at least $4$, which does not have any chord, leading to a contradiction. Hence, $v_{i_l}$ has at least one chord attached to it in $C$. Let $v_{i_l}y$ be one such chord; then we show that $y$ lies in $P(v'_1,x'_1)$ in the next claim.

    \begin{claim}\label{claim:chord}
        $y$ lies in $P(v'_1,x'_1)$.
    \end{claim}

    \begin{proof}
        If $y$ does not lie in  $P(v'_1,x'_1)$, then $y$ must lie in the path between $v_{i_l}$ and $x'_1$ (or the path between $v_{i_l}$ and $v'_1$). If it lies on the path between $v_{i_l}$ and $x'_1$ (resp. between $v_{i_l}$ and $v'_1$), then we have a path from $v_{i_l}$ to $x'$  (resp. between $v_{i_l}$ and $v'$) which has length smaller than $d(v_{i_l},x')$ (resp. $d(v_{i_l},v')$), which is a contradiction. Hence,  $y$ lies in $P(v'_1,x'_1)$ (refer to Figure \ref{fig:main_proof_2}).
    \end{proof}

    \noindent Note that $d(x'_1,y)\geq d(x'_1,v_{i_l})$ and $d(v'_1,y)\geq d(v'_1,v_{i_l})$. If not, then there exists a shorter or equal length path from $v'$ to $v_{i_l}$ (from $x'$ to $v_{i_l}$) that bypasses the edge $v_{i_l}v$ (resp. $v_{i_l}x$), which is a contradiction to the fact that the pair $v_{i_l},v'$ (resp. $v_{i_l},x'$) monitors the edge $v_{i_l}v$ (resp. $v_{i_l}x$). Hence $d_P(x'_1,v'_1)=d(x'_1,y)+d(y,v'_1)\geq d(v'_1,v_{i_l})+d(x'_1,v_{i_l})$, implying $d_P(x'_1,v'_1)= d(v'_1,v_{i_l})+d(x'_1,v_{i_l})$. This implies that $d(x'_1,y)=d(x'_1,v_{i_l})$ and $d(v'_1,y)=d(v'_1,v_{i_l})$, which implies that the vertex $y$ is unique in $P(v'_1,x'_1)$. This fact together with Claim~\ref{claim:chord} implies that in $C$, $v_{i_l}$ is incident to exactly one chord. 

    \smallskip
    \noindent Now note that if $v$ and $y$ are not adjacent, then the induced $2$-path $yv_{i_l}v$ is part of a chordless cycle of length at least $4$, which is a contradiction. Hence $vy\in E(G_{k+1})$. Similarly, it can be shown that $xy\in E(G_{k+1})$. Hence $vv_{i_l}x$ is part of a $4$-cycle $vv_{i_l}xyv$, which leads to a contradiction. Hence $v'$ and $x'$ monitor $vv_{i_l}$. 


    \smallskip
    \noindent Hence, until now, we showed that all edges in $E_l$ can be monitored by the vertices of $Man(G_k)\setminus \{v_{i_l}\}$. Hence, combining this fact with Claim \ref{Claim_5.1} and \ref{Claim_5.2}, we can conclude that $Man(G_{k+1})$ forms an optimal MEG set of $G_{k+1}$. Hence, $meg(G)=\vert Man(G)\vert$ for every strongly chordal graph $G$.  
\end{proof}

\section{Conclusion and future aspects}
\label{sec:conclusion}
In this paper, we solved the complexity status of the MIN-MEG problem for some well-known graph classes. Next, it will be interesting to address the following questions:

\begin{question}
    For any bipartite permutation graph $G$, we showed that $Man(G)=V\setminus Cut(G)$, and the graph mentioned in~\cite[Figure 4]{DBLP:journals/corr/abs-2403-09122} (a path on six vertices with an added universal vertex, which is a permutation graph) shows that this is not always the case for permutation graphs. However, do we have $|Man(G)|=meg(G)$ when $G$ is a permutation graph?
\end{question}

\begin{question}
    For any strongly chordal graph $G$, we showed that $|Man(G)|=meg(G)$, and this was also shown to be true for well-partitioned chordal graphs in~\cite{DBLP:journals/corr/abs-2403-09122,DBLP:conf/caldam/FoucaudMMSST24}. Does this property hold for chordal graphs as well?
\end{question}

\begin{question}
    As can be seen in Figure~\ref{fig:diagram}, the complexity status of the MIN-MEG problem is open for graph classes such as circle graphs, permutation graphs, chordal graphs, cocomparability graphs, etc. Is the MIN-MEG problem efficiently solvable for these graph classes?
\end{question}



